522:       // Em produção, adicionar também: cpf_mascarado, numero_carteirinha,
523:       // validade, plano, codigo_beneficiario…
524:     };
525: 
526:     /* --- SKETCH DE IMPLEMENTAÇÃO REAL (descomentar em produção) -----------
527:     const formData = new FormData();
528:     formData.append('document', source);
529:     const res = await fetch('https://api.saudemasplus.com/v1/ocr/scan', {
