565: /**
566:  * chatService.open(ticket)
567:  * -----------------------------------------------------------------------------
568:  * PONTO DE INTEGRAÇÃO REAL — Chat de atendimento.
569:  * Opções: WebSocket próprio, Twilio Conversations, Intercom, Zendesk Sunshine,
570:  * ou SDK de mensageria hospitalar. Deve herdar o `ticket` para que o
571:  * atendente já abra a conversa com o contexto do paciente.
572:  */
573: const chatService = {
574:   async open(ticket) {
575:     // DEMO: apenas loga a intenção.
576:     console.info('[chatService] abriria conversa para o chamado', ticket);
577:     return { ok: true, ticket };
578:   }
579: };
