581: /** analyticsService.track(event, props) — PONTO DE INTEGRAção: telemetria.
582:  *  Produção: Oracle Analytics / GA4 / Mixpanel. Use para alimentar a métrica
583:  *  de "tempo médio de recepção" exibida no rodapé da tela de sucesso. */
584: const analyticsService = {
585:   track(event, props = {}) {
586:     console.info('[analytics]', event, props);
587:   },
588:   /** Navegação entre telas (alias para track, mantido explícito por clareza). */
589:   screenView(screenName) {
590:     this.track('screen_view', { screen: screenName });
591:   }
592: };
593: 
594: /* --------------------------------------------------------------------------
595:    2. ESTADO DA APLICAÇÃO
596:    -------------------------------------------------------------------------- */
597: 
598: const INERTIA_TIMEOUT_MS = 10_000; // 10 segundos — timer global de inércia
599: 
600: /* Telas em que o timer de inércia está ARMADO.
601:    Conforme spec: "qualquer tela do fluxo de check-in" — ou seja, a Tela 1
602:    (dupla rota) e a Tela 2 (check-in rápido). A Tela 4 fica de fora:
603:    o atendente já foi acionado, não faz sentido pressionar o usuário. */
604: const INERTIA_SCREENS = ['inicio', 'checkin'];
605: 
606: const state = {
607:   screen: 'inicio',          // 'inicio' | 'checkin' | 'suporte'
608:   docScanned: false,         // documento já lido pelo OCR?
609:   inertiaTimer: null,        // handle do setTimeout da inércia
610:   inertiaModalOpen: false,
611:   ticket: null,              // nº do chamado de suporte
612:   lastInertiaReason: null
613: };
614: 
615: /* --------------------------------------------------------------------------
616:    3. REFERÊNCIAS DO DOM
617:    -------------------------------------------------------------------------- */
618: const $ = (id) => document.getElementById(id);
619: 
620: const screens = {
621:   inicio:   $('screen-inicio'),
622:   checkin:  $('screen-checkin'),
623:   suporte:  $('screen-suporte')
624: };
625: 
626: const el = {
627:   statusText:   $('statusText'),
628:   statusDot:    $('statusDot'),
629:   // Tela 1
630:   btnRota1:     $('btnRota1'),
631:   btnRota2:     $('btnRota2'),
632:   // Tela 2
633:   btnScan:      $('btnScan'),
634:   btnConfirmar: $('btnConfirmar'),
635:   btnVoltarAjuda: $('btnVoltarAjuda'),
636:   btnManual:    $('btnManual'),
637:   scanIdle:     $('scanIdle'),
638:   scanLoading:  $('scanLoading'),
639:   scanDone:     $('scanDone'),
640:   formResult:   $('formResult'),
641:   fNome:        $('fNome'),
642:   fConvenio:    $('fConvenio'),
643:   fConsulta:    $('fConsulta'),
644:   dicaConfirmar:$('dicaConfirmar'),
645:   // Tela 4
646:   ticketChip:   $('ticketChip'),
647:   btnChat:      $('btnChat'),
648:   btnReiniciar: $('btnReiniciar'),
649:   // Overlays
650:   inertiaModal: $('inertiaModal'),
651:   inertiaYes:   $('inertiaYes'),
652:   inertiaNo:    $('inertiaNo'),
653:   callOverlay:  $('callOverlay'),
654:   toast:        $('toast')
655: };
656: 
657: /* --------------------------------------------------------------------------
658:    4. NAVEGAÇÃO ENTRE ESTADOS (state machine)
659:    -------------------------------------------------------------------------- */
660: 
661: /**
662:  * goTo(screen) — troca a tela visível e ajusta o status do cabeçalho.
663:  * @param {'inicio'|'checkin'|'suporte'} screen
664:  */
665: function goTo(screen) {
666:   if (!screens[screen]) return;
667: 
668:   state.screen = screen;
669: 
670:   // Oculta todas, exibe a alvo (mantém uma única tela no DOM visível).
671:   Object.values(screens).forEach(s => { s.hidden = true; });
672:   screens[screen].hidden = false;
673: 
674:   // Feedback no header (aria-live já está no elemento).
675:   const statusMap = {
676:     inicio:   'Aguardando você',
677:     checkin:  'Check-in em andamento',
678:     suporte:  'Atendente a caminho'
679:   };
680:   el.statusText.textContent = statusMap[screen] || '';
681: 
682:   // Rola para o topo — importante em mobile quando a tela tem scroll.
683:   window.scrollTo({ top: 0, behavior: 'smooth' });
684: 
685:   // Regra de inércia: arma nas telas do fluxo de check-in, desarma fora.
686:   if (INERTIA_SCREENS.includes(screen)) {
687:     startInertia();
688:   } else {
689:     stopInertia();
690:   }
691: 
692:   analyticsService.screenView(screen);
693: }
694: 
695: /* --------------------------------------------------------------------------
696:    5. SISTEMA PROATIVO DE INÉRCIA (ANTI-TRAVAMENTO)
697:    --------------------------------------------------------------------------
698:    • Timer GLOBAL de 10s: reinicia com QUALQUER interação do usuário.
699:    • Só está ativo no fluxo de check-in (Tela 2), conforme especificado.
700:    • Ao estourar, abre o modal empático bloqueando a ação atual.
701:    • "Continuar sozinho" reabre o timer; "Sim" cancela e vai à Tela 4.
702:    -------------------------------------------------------------------------- */
703: 
704: function startInertia() {
705:   stopInertia();
706:   state.inertiaTimer = setTimeout(onInertiaExpired, INERTIA_TIMEOUT_MS);
707: }
708: 
709: function stopInertia() {
710:   if (state.inertiaTimer) {
711:     clearTimeout(state.inertiaTimer);
712:     state.inertiaTimer = null;
713:   }
714: }
715: 
716: /** Chamado quando o usuário fica 10s sem interagir. */
717: function onInertiaExpired() {
718:   if (!INERTIA_SCREENS.includes(state.screen) || state.inertiaModalOpen) return;
719:   openInertiaModal();
720:   analyticsService.track('inertia_triggered', { screen: state.screen });
721: }
722: 
723: function openInertiaModal() {
724:   state.inertiaModalOpen = true;
725:   stopInertia(); // pausa o timer enquanto o modal está aberto
726:   el.inertiaModal.classList.remove('hidden');
727:   el.inertiaModal.classList.add('flex');
728:   // Foco no CTA principal (a11y: foco deve entrar no diálogo).
729:   requestAnimationFrame(() => el.inertiaYes.focus());
730: }
731: 
732: function closeInertiaModal() {
733:   state.inertiaModalOpen = false;
734:   el.inertiaModal.classList.add('hidden');
735:   el.inertiaModal.classList.remove('flex');
736: }
737: 
738: /** Reseta o timer em QUALQUER interação (clique, toque, teclado, scroll). */
739: function bumpInertia() {
740:   if (INERTIA_SCREENS.includes(state.screen) && !state.inertiaModalOpen) startInertia();
741: }
742: 
743: // Registrado uma única vez no documento — cobre todos os gestos.
744: ['pointerdown', 'keydown', 'wheel', 'touchstart'].forEach(evt => {
745:   document.addEventListener(evt, bumpInertia, { passive: true });
746: });
747: 
748: /* --------------------------------------------------------------------------
749:    6. TELA 1 — A DUPLA ROTA
750:    -------------------------------------------------------------------------- */
751: 
752: el.btnRota1.addEventListener('click', () => {
753:   analyticsService.track('route_selected', { route: 'autonomous' });
754:   goTo('checkin');
755: });
756: 
757: /** ROTA 2: chamado humano imediato — overlay visual → Tela de sucesso. */
758: el.btnRota2.addEventListener('click', async () => {
759:   analyticsService.track('route_selected', { route: 'human' });
760: 
761:   // 1) Overlay "Chamando recepção…" (feedback imediato = percepção de velocidade)
762:   el.callOverlay.classList.remove('hidden');
763:   el.callOverlay.classList.add('flex');
764:   el.statusText.textContent = 'Chamando recepção…';
765: 
766:   // 2) Dispara o chamado no sistema de fila (aqui: simulado ~1.6s)
767:   const res = await queueService.dispatch('ROTA_1_HUMAN_BUTTON');
768:   await new Promise(r => setTimeout(r, 1600));
769: 
770:   // 3) Esconde overlay e segue para a Tela 4 (Sucesso / Suporte acionado)
771:   el.callOverlay.classList.add('hidden');
772:   el.callOverlay.classList.remove('flex');
773: 
774:   state.ticket = res.ticket;
775:   goTo('suporte');
776: });
777: 
778: /* --------------------------------------------------------------------------
779:    7. TELA 2 — CHECK-IN RÁPIDO (OCR SIMULADO)
780:    -------------------------------------------------------------------------- */
781: 
782: el.btnScan.addEventListener('click', async () => {
783:   if (state.docScanned) {
784:     // Re-escanear: reinicia o fluxo.
785:     resetScanUI();
786:     return;
787:   }
788: 
789:   // --- UI: estado de carregamento ---------------------------------------
790:   el.btnScan.disabled = true;
791:   el.btnScan.classList.add('opacity-60', 'cursor-wait');
792:   el.scanIdle.hidden = true;
793:   el.scanDone.hidden = true;
794:   el.scanLoading.hidden = false;
795:   el.statusText.textContent = 'Lendo documento…';
