797:   /* PONTO DE INTEGRAÇÃO REAL — captura da imagem:
798:      Em produção, aqui sairíamos de uma dessas fontes:
799:        a) <input type="file" accept="image/*" capture="environment">
800:           (câmera traseira nativa — recomendado para idosos, zero permissão extra);
801:        b) getUserMedia({ video: { facingMode: 'environment' } }) + <canvas>
802:           para um visor de câmera customizado com guias de alinhamento;
803:        c) Upload de arquivo já existente (galeria).
804:      O blob resultante seria enviado ao ocrService.scan(). */
805:   const capturedFile = null; // demo: sem arquivo real
806: 
807:   try {
808:     // --- Chamada ao serviço (2s simulados dentro do serviço) -------------
809:     const data = await ocrService.scan(capturedFile);
810: 
811:     // --- Preenchimento automático dos campos ----------------------------
812:     el.fNome.value     = data.nome;
813:     el.fConvenio.value = data.convenio;
814:     el.fConsulta.value = data.consulta;
