817:     el.formResult.dataset.filled = 'true';
818:     state.docScanned = true;
819: 
820:     // --- Transição de UI: sucesso ----------------------------------------
821:     el.scanLoading.hidden = true;
822:     el.scanDone.hidden = false;
823: 
824:     el.btnScan.disabled = false;
825:     el.btnScan.classList.remove('opacity-60', 'cursor-wait');
826:     el.btnScan.innerHTML = '🔄 Escanear novamente';
827: 
