/* --------------------------------------------------------------------------
   7. TELA 2 — CHECK-IN RÁPIDO (CAPTURA REAL + OCR SIMULADO)
   -------------------------------------------------------------------------- */

/**
 * openCapture() — abre o seletor nativo de imagem.
 * No celular com `capture="environment"` isso lança a CÂMERA TRASEIRA direto.
 * Tratamos os 3 desfechos possíveis do diálogo nativo:
 *   1) arquivo escolhido  → OCR real (demo: 2s + dados sintéticos);
 *   2) evento 'cancel'     → usuário desistiu → modo demonstração;
 *   3) navegador antigo    → sem 'cancel': heurística por volta de foco.
 */
function openCapture() {
  let settled = false;

  const finish = (file) => {
    if (settled) return;
    settled = true;
    el.fileInput.removeEventListener('change', onChange);
    el.fileInput.removeEventListener('cancel', onCancel);
    window.removeEventListener('focus', onFocus);
    runOcr(file);
  };

  function onChange() {
    const f = el.fileInput.files && el.fileInput.files[0];
    if (f) finish(f); // caso contrário, deixa o 'cancel'/foco decidir
  }
  function onCancel() { finish(null); }
  function onFocus() {
    // Heurística para navegadores sem o evento 'cancel' (Chrome <113, Safari <16.4):
    // ao voltar o foco à janela, aguardamos 700ms (tempo do diálogo fechar)
    // e seguimos com o modo demo caso nenhum arquivo tenha sido selecionado.
    setTimeout(() => finish(el.fileInput.files[0] || null), 700);
  }

  el.fileInput.addEventListener('change', onChange);
  el.fileInput.addEventListener('cancel', onCancel);
  if (!('oncancel' in el.fileInput)) window.addEventListener('focus', onFocus);

  // Reset para permitir escolher o MESMO arquivo de novo em re-escaneamentos.
  el.fileInput.value = '';
  el.fileInput.click();
}

el.btnScan.addEventListener('click', () => {
  if (state.scanning) return;          // ignora toques durante o OCR
  if (state.docScanned) {              // re-escanear: reinicia o fluxo
    resetScanUI();
    return;
  }
  openCapture();
});

/**
 * runOcr(file) — orquestra loading → OCR → preenchimento → sucesso.
 * @param {File|null} file — foto capturada (null = modo demonstração)
 */
async function runOcr(file) {
  if (state.scanning) return;
  state.scanning = true;

  // --- UI: estado de carregamento ---------------------------------------
  el.btnScan.disabled = true;
  el.btnScan.classList.add('opacity-60', 'cursor-wait');
  el.scanIdle.hidden = true;
  el.scanDone.hidden = true;
  el.scanLoading.hidden = false;
  el.statusText.textContent = 'Lendo documento…';

  // Pré-visualização real (se houver arquivo), com ObjectURL revogável.
  if (file) {
    if (state.previewUrl) URL.revokeObjectURL(state.previewUrl);
    state.previewUrl = URL.createObjectURL(file);
    el.scanPreview.src = state.previewUrl;
    el.scanPreview.hidden = false;
  }

  try {
    // --- Chamada ao serviço (2s simulados dentro do serviço) -------------
    const data = await ocrService.scan(file);

    // --- Preenchimento automático dos campos ----------------------------
    el.fNome.value     = data.nome;
    el.fConvenio.value = data.convenio;
    el.fConsulta.value = data.consulta;

    // Sinaliza "preenchido" (guarda de validação do botão Confirmar).
    el.formResult.dataset.filled = 'true';
    state.docScanned = true;

    // --- Transição de UI: sucesso ----------------------------------------
    el.scanLoading.hidden = true;
    el.scanDone.hidden = false;

    el.btnScan.disabled = false;
    el.btnScan.classList.remove('opacity-60', 'cursor-wait');
    el.btnScan.innerHTML = '🔄 Escanear novamente';

    // Libera a ação finalizadora.
    el.btnConfirmar.disabled = false;
    el.dicaConfirmar.textContent = 'Confirme para concluir seu check-in.';
    el.statusText.textContent = 'Documento identificado ✓';

    showToast(file ? '✅ Documento lido! Confira os dados.'
                   : '✅ Leitura concluída (modo demonstração).');
    analyticsService.track('ocr_success', {
      confidence: data.confidence,
      mode: file ? 'captured' : 'demo'
    });

  } catch (err) {
    // --- Tratamento de erro (rede/API indisponível, imagem ilegível) -----
    console.error('[OCR]', err);
    resetScanUI();
    showToast('⚠️ Não conseguimos ler o documento. Tente novamente ou digite manualmente.', 4200);
    analyticsService.track('ocr_failure', { error: String(err) });
  } finally {
    state.scanning = false;
  }
}

