$h = Get-Content -Raw 'fluxo-dual.html'
# 1) IDs duplicados + refs $\('..') ausentes
$ids = [regex]::Matches($h, 'id="([^"]+)"') | ForEach-Object { $_.Groups[1].Value }
$dup = $ids | Group-Object | Where-Object { $_.Count -gt 1 }
if ($dup) { "IDS DUPLICADOS: " + (($dup | ForEach-Object { $_.Name }) -join ', ') } else { "OK: sem ids duplicados ($($ids.Count))" }
$refs = [regex]::Matches($h, "[`$]\('([^']+)'\)") | ForEach-Object { $_.Groups[1].Value } | Sort-Object -Unique
$missing = $refs | Where-Object { $ids -notcontains $_ }
if ($missing) { "REFS AUSENTES: " + ($missing -join ', ') } else { "OK: todas as $($refs.Count) refs existem no DOM" }

# 2) balanceamento do script da aplicacao
$m = [regex]::Matches($h, '(?s)<script>(.*?)</script>')
$js = $m[$m.Count-1].Groups[1].Value
$stack = New-Object System.Collections.Stack
$pairs = @{ '{'='}'; '('=')'; '['=']' }
$closing = @{ '}'='{'; ')'='('; ']'='[' }
$line=1; $i=0; $state='code'; $err=$null
while ($i -lt $js.Length -and -not $err) {
  $c = $js[$i]
  if ($c -eq "`n") { $line++ }
  switch ($state) {
    'code' {
      if ($c -eq '/' -and $i+1 -lt $js.Length -and $js[$i+1] -eq '/') { $state='line'; $i++ }
      elseif ($c -eq '/' -and $i+1 -lt $js.Length -and $js[$i+1] -eq '*') { $state='block'; $i++ }
      elseif ($c -eq "'") { $state='sq' }
      elseif ($c -eq '"') { $state='dq' }
      elseif ($c -eq '`') { $state='tpl' }
      elseif ($pairs.ContainsKey("$c")) { [void]$stack.Push(@{c="$c";line=$line}) }
      elseif ($closing.ContainsKey("$c")) {
        if ($stack.Count -eq 0) { $err = "linha ${line}: '$c' fecha sem abrir" }
        elseif ($stack.Peek().c -ne $closing["$c"]) { $err = "linha ${line}: '$c' nao fecha '$($stack.Peek().c)' (linha $($stack.Peek().line))" }
        else { [void]$stack.Pop() }
      }
    }
    'line' { if ($c -eq "`n") { $state='code' } }
    'block' { if ($c -eq '*' -and $i+1 -lt $js.Length -and $js[$i+1] -eq '/') { $state='code'; $i++ } }
    'sq' { if ($c -eq '\') { $i++ } elseif ($c -eq "'") { $state='code' } }
    'dq' { if ($c -eq '\') { $i++ } elseif ($c -eq '"') { $state='code' } }
    'tpl' { if ($c -eq '\') { $i++ } elseif ($c -eq '`') { $state='code' } }
  }
  $i++
}
if ($err) { "JS ERRO: $err" }
elseif ($stack.Count -gt 0) { "JS ERRO: $($stack.Count) nao fechado(s)" }
else { "JS OK: balanceado, estado final '$state', $line linhas" }

# 3) handlers registrados vs ids
$handlers = [regex]::Matches($js, "el\.(\w+)\.addEventListener") | ForEach-Object { $_.Groups[1].Value } | Sort-Object -Unique
"handlers em el.*: $($handlers -join ', ')"

