/**
 * aiService.reply(userMessage, context)
 * -----------------------------------------------------------------------------
 * PONTO DE INTEGRAÇÃO REAL — CHAT DE AJUDA COM INTELIGÊNCIA ARTIFICIAL.
 *
 * Nesta PoC a resposta é gerada por um motor de regras local (offline, sem
 * custo, determinístico). Em produção, troque o corpo por uma chamada a um
 * LLM com RAG sobre a cartela de planos/protocolos da clínica.
 *
 * Opção A — Oracle Cloud Infrastructure (OCI) Generative AI (Chat API):
 *   Endpoint: POST https://generativeai.oci.{region}.oraclecloud.com/v1/chatCompletions
 *   Modelo:   "cohere.command" ou meta/llama-3.x (ou model customizado)
 *   Auth:     OCI SDK / API key (never exposta no browser — use um backend
 *             proxy/edge function para assinar a requisição)
 *   Body: {
 *     "compartmentId": "...",
 *     "model": "cohere.command",
 *     "chatHistory": [{ "role":"SYSTEM", "content": "<persona + regras>" }, ...],
 *     "message": userMessage
 *   }
 *
 * Opção B — OpenAI-compatible (OpenAI / Azure OpenAI / local vLLM):
 *   POST https://api.exemplo.com/v1/chat/completions  { model, messages, temperature: 0.3 }
 *
 * REGRAS DE SEGURANÇA EM SAÚDE (obrigatórias no system prompt):
 *   1. NUNCA dar diagnóstico, dosagem ou conduta clínica — sempre escalar.
 *   2. Emergência → "Ligue 192 (SAMU)" e acionar recepção imediatamente.
 *   3. Só confirmar dados que já existem no contexto (nome/plano/consulta);
 *      nunca inventar horário, cobertura ou disponibilidade de médico.
 *   4. LGPD: não enviar CPF/RG completo ao modelo; minimizar dados no payload.
 *
 * Contexto enviado ao modelo (para respostas personalizadas):
 *   { nome, convenio, consulta, ticket } — vindo do estado do app.
 *
 * @param {string} userMessage — texto digitado pelo paciente
 * @param {object} context     — { nome, convenio, consulta, screen }
 * @returns {Promise<string>}  — resposta da IA em texto simples
 */
const aiService = {
  async reply(userMessage, context = {}) {
    const msg = (userMessage || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    // Simula latência humana de digitação (400–1100ms) para dar credibilidade.
    await new Promise(r => setTimeout(r, 400 + Math.random() * 700));

    // --- DETECÇÃO DE PLANO DE SAÚDE MENCIDO NA CONVERSA ------------------
    // Se o paciente escrever o nome do plano ("meu plano é unimed"), a IA
    // registra automaticamente no formulário de check-in (preenchimento
    // conversacional — ótimo para idosos que não acham o <select>).
    const planosCatalogo = [
      'saude total', 'unimed', 'bradesco saude', 'sulamerica',
      'amil', 'porto seguro saude', 'careplus', 'particular'
    ];
    const planoMencionado = planosCatalogo.find(p => msg.includes(p));
    if (planoMencionado && /(meu plano|plano e|plano eh|tenho|uso|sou|fazer cadastro|meu convenio)/.test(msg)) {
      aplicarPlano(planoMencionado);
      const nomeExibicao = planoMencionado.replace(/\b\w/g, c => c.toUpperCase());
      return `Perfeito! Registrei seu plano como **${nomeExibicao}** no seu check-in. ✔️\n\n` +
             `Você pode conferir no campo "Qual é o seu plano de saúde?" — se estiver errado, é só trocar por lá.`;
    }

    // --- MOTOR DE RESPOSTAS (demo offline) --------------------------------
    if (/\b(oi|ola|bom dia|boa tarde|boa noite|e ai)\b/.test(msg)) {
      return `Olá${context.nome && context.nome !== '—' ? ', ' + context.nome.split(' ')[0] : ''}! 👋 ` +
             `Sou a assistente virtual da Clínica Saúde+. Posso ajudar com plano de saúde, horários, documentos e o caminho até a sala.`;
    }
    if (/(plano|convenio)/.test(msg)) {
      const atual = currentPlano();
