/* --------------------------------------------------------------------------
   3-B. PLANO DE SAÚDE — helpers de leitura/escrita do <select>
   --------------------------------------------------------------------------
   Ponto único de verdade para o campo de plano, usado pelo OCR, pelo
   preenchimento manual e pela conversa com a IA.
   -------------------------------------------------------------------------- */

/** Retorna o plano atual ('' se nada selecionado). */
function currentPlano() {
  return el.fPlano.value || '';
}

/**
 * Aplica um plano ao select.
 * - Se existir opção correspondente, seleciona;
 * - Se não existir (plano fora da lista), CRIA a opção e seleciona —
 *   nunca devemos perder a informação só porque o catálogo é fixo.
 * @param {string} nome — nome do plano ("unimed", "Saúde Total", …)
 */
function aplicarPlano(nome) {
  if (!nome) return;
  const alvo = String(nome).trim();

  // Match tolerante: ignora acentos/caixa ("SulAmérica" vs "sulamerica").
  const norm = (s) => s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  let opt = Array.from(el.fPlano.options).find(o => norm(o.value) === norm(alvo));

  if (!opt) {
    // Valor vindo do OCR que não está no catálogo → cria dinamicamente.
    const display = alvo.replace(/\b\w/g, c => c.toUpperCase()); // "unimed" → "Unimed"
    opt = new Option(display, display);
    el.fPlano.add(opt);
  }

  el.fPlano.value = opt.value;
  refreshConfirm();
  updatePlanChip();
}

/**
 * Habilita/desabilita o "Confirmar" conforme as regras de negócio:
 * documento escaneado E plano escolhido.
 */
function refreshConfirm() {
  const ok = state.docScanned && el.fPlano.value !== '';
  el.btnConfirmar.disabled = !ok;

  if (!state.docScanned) {
    el.dicaConfirmar.textContent = 'Escaneie o documento para liberar a confirmação.';
  } else if (el.fPlano.value === '') {
    el.dicaConfirmar.textContent = 'Selecione seu plano de saúde para continuar.';
  } else {
    el.dicaConfirmar.textContent = 'Confirme para concluir seu check-in.';
  }
}

/** Reflete o plano escolhido no chip da Tela 4. */
function updatePlanChip() {
  const p = currentPlano();
  if (p) {
    el.planChip.hidden = false;
    el.planChipText.textContent = 'Plano: ' + p;
  } else {
    el.planChip.hidden = true;
  }
}

// Mudança manual no dropdown também revalida o CTA.
el.fPlano.addEventListener('change', () => {
  refreshConfirm();
  updatePlanChip();
  bumpInertia(); // conta como interação no timer de inércia
});

/* --------------------------------------------------------------------------
   4. NAVEGAÇÃO ENTRE ESTADOS (state machine)
   -------------------------------------------------------------------------- */

