input.newString:
/* --------------------------------------------------------------------------
   9. CHAT DE AJUDA COM IA
   --------------------------------------------------------------------------
   • Renderização de bolhas (usuário / assistente) com suporte a **negrito**
     simples via markdown leve (escape HTML antes de aplicar).
   • Indicador "digitando…" enquanto a IA responde.
   • Chips de resposta rápida (inclui atalho de plano de saúde).
   • CTA inline "Acionar recepção" quando a IA entende pedido de humano.
   • Pausa o timer de inércia enquanto aberto (usuário está engajado).
   -------------------------------------------------------------------------- */

/** Escapa HTML do usuário antes de qualquer render (proteção XSS). */
function escapeHtml(str) {
  return String(str).replace(/[&<>"']/g, c => (
    { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]
  ));
}

/** Markdown leve: **negrito** → <strong>. Só após o escape. */
function renderRich(text) {
  return escapeHtml(text)
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/\n/g, '<br>');
}

/** Adiciona uma bolha na conversa. */
function addBubble(from, text, { cta = false } = {}) {
  const wrap = document.createElement('div');
  wrap.className = from === 'user' ? 'flex justify-end' : 'flex justify-start';

  const bubble = document.createElement('div');
  bubble.className = from === 'user'
    ? 'max-w-[85%] rounded-2xl rounded-br-md bg-brand-700 px-4 py-2.5 text-[14px] leading-relaxed text-white shadow-sm'
    : 'max-w-[85%] rounded-2xl rounded-bl-md border border-slate-200 bg-white px-4 py-2.5 text-[14px] leading-relaxed text-slate-800 shadow-sm';
  bubble.innerHTML = renderRich(text);
  wrap.appendChild(bubble);

  // CTA: botão de escalonamento para atendimento humano.
  if (cta) {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'btn-tactile mt-2 w-full rounded-xl bg-brand-700 px-4 py-3 text-[14px] font-extrabold text-white shadow hover:bg-brand-800 focus:outline-none focus-visible:ring-4 focus-visible:ring-brand-400';
    btn.textContent = '🙋 Acionar a recepção agora';
    btn.addEventListener('click', escalateFromChat);
    // Empilha bolha + botão verticalmente.
    const col = document.createElement('div');
    col.className = 'flex max-w-[85%] flex-col';
    col.appendChild(bubble);
    col.appendChild(btn);
    wrap.innerHTML = '';
    wrap.appendChild(col);
  }

  el.chatMessages.appendChild(wrap);
  el.chatMessages.scrollTop = el.chatMessages.scrollHeight;
}

/** Indicador de "digitando…". Retorna função para removê-lo. */
function showTyping() {
  const wrap = document.createElement('div');
  wrap.className = 'flex justify-start';
  wrap.dataset.typing = '1';
  wrap.innerHTML =
    '<div class="flex items-center gap-1.5 rounded-2xl rounded-bl-md border border-slate-200 bg-white px-4 py-3.5 shadow-sm">' +
      '<span class="h-2 w-2 animate-bounce rounded-full bg-slate-400 [animation-delay:-.3s]"></span>' +
      '<span class="h-2 w-2 animate-bounce rounded-full bg-slate-400 [animation-delay:-.15s]"></span>' +
      '<span class="h-2 w-2 animate-bounce rounded-full bg-slate-400"></span>' +
    '</div>';
  el.chatMessages.appendChild(wrap);
  el.chatMessages.scrollTop = el.chatMessages.scrollHeight;
  return () => wrap.remove();
}

/** Chips de resposta rápida. */
function renderChips() {
  const chips = [
    'Qual planos vocês aceitam?',
    'Meu plano é Unimed',        // demonstra o preenchimento conversacional
    'Qual é minha consulta?',
    'Onde fica a sala de espera?',
    'Preciso de ajuda'
  ];
  el.chatChips.innerHTML = '';
  chips.forEach(label => {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'shrink-0 whitespace-nowrap rounded-full border border-brand-300 bg-white px-3.5 py-2 text-[12.5px] font-semibold text-brand-800 transition hover:bg-brand-50 focus:outline-none focus-visible:ring-4 focus-visible:ring-brand-400';
    b.textContent = label;
    b.addEventListener('click', () => sendChat(label));
    el.chatChips.appendChild(b);
  });
}

/** Envio de mensagem (chips e formulário passam por aqui). */
async function sendChat(text) {
  const msg = (text || '').trim();
  if (!msg) return;

  addBubble('user', msg);
  el.chatInput.value = '';
  el.chatChips.innerHTML = ''; // limpa chips durante o processamento
  analyticsService.track('chat_sent', { len: msg.length });

  const hideTyping = showTyping();

  const context = {
    nome:     el.fNome.value,
    convenio: currentPlano(),
    consulta: el.fConsulta.value,
    screen:   state.screen
  };

  const reply = await aiService.reply(msg, context);
  hideTyping();

  // Escalonamento: se a IA detectou pedido de humano, oferece CTA.
  const wantsHuman = /(atendente|humano|recepcao|falar com alguem|ajuda)/i.test(
    msg.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  ) && !/^(oi|ola|bom dia|boa tarde|boa noite)/.test(msg.trim().toLowerCase());

  addBubble('bot', reply, { cta: wantsHuman });
  renderChips(); // restaura chips
  el.chatInput.focus();
}

/** Escalonamento a partir do chat → Tela 4 (suporte ativo). */
async function escalateFromChat() {
  const res = await queueService.dispatch('AI_CHAT_ESCALATION');
  state.ticket = res.ticket;
  analyticsService.track('chat_escalated', { ticket: res.ticket });
  closeChat();
  goTo('suporte');
  showToast('🙋 Recepção acionada pelo chat.');
}

/** Abre o painel do chat. */
function openChat() {
  state.chatOpen = true;
  el.chatPanel.hidden = false;
  stopInertia(); // pausa o anti-travamento enquanto conversa

  // Boas-vindas única por sessão.
  if (!state.chatBooted) {
    state.chatBooted = true;
    addBubble('bot',
      'Olá! 👋 Sou a assistente da Clínica Saúde+.\n\n' +
      'Posso ajudar com **plano de saúde**, **horário da consulta**, ' +
      '**documentos** e o **caminho até a sala**. Como posso te ajudar?');
    renderChips();
  }

  analyticsService.track('chat_opened', { screen: state.screen });
  requestAnimationFrame(() => el.chatInput.focus({ preventScroll: true }));
}

/** Fecha o painel do chat e retoma o fluxo. */
function closeChat() {
  state.chatOpen = false;
  el.chatPanel.hidden = true;
  // Retoma inércia apenas se estiver numa tela do fluxo de check-in.
  if (INERTIA_SCREENS.includes(state.screen)) startInertia();
}

// Gatilhos de abertura.
el.btnOpenChat.addEventListener('click', openChat);
el.btnIaLink.addEventListener('click', openChat);
el.btnChat.addEventListener('click', openChat); // Tela 4: "abra o chat abaixo"
el.chatClose.addEventListener('click', closeChat);

// Envio pelo formulário.
el.chatForm.addEventListener('submit', (e) => {
  e.preventDefault();
  sendChat(el.chatInput.value);
});

// Esc fecha o chat (se aberto) — a11y.
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && state.chatOpen) closeChat();
});

/* --------------------------------------------------------------------------
   9-B. TELA 4 — SUPORTE ACIONADO
   -------------------------------------------------------------------------- */

