/** Escapa HTML do usuário antes de qualquer render (proteção XSS).
 *  split/join em vez de regex para aspas: evita quote dentro de literal
 *  de regex (ambíguo para parsers simples e para minificadores antigos). */
function escapeHtml(str) {
  return String(str)
    .split('&').join('&amp;')
    .split('<').join('&lt;')
    .split('>').join('&gt;')
    .split('"').join('&quot;')
    .split("'").join('&#39;');
}

