input.content:
param([string]$Arquivo)

$h = Get-Content -Raw $Arquivo
$resultados = @()

# 1) IDs duplicados
$ids = [regex]::Matches($h, 'id="([^"]+)"') | ForEach-Object { $_.Groups[1].Value }
$dup = $ids | Group-Object | Where-Object { $_.Count -gt 1 }
if ($dup) {
  $resultados += "ERRO ids duplicados: " + (($dup | ForEach-Object { $_.Name }) -join ', ')
} else {
  $resultados += "OK  ids ($($ids.Count)) sem duplicatas"
}

# 2) refs $('..')
$refs = [regex]::Matches($h, "[`$]\('([^']+)'\)") | ForEach-Object { $_.Groups[1].Value } | Sort-Object -Unique
$missing = $refs | Where-Object { $ids -notcontains $_ }
if ($missing) {
  $resultados += "ERRO refs ausentes: " + ($missing -join ', ')
} else {
  $resultados += "OK  refs ($($refs.Count)) todas existem no DOM"
}

# 3) labels com alvo
$labels = [regex]::Matches($h, 'for="([^"]+)"') | ForEach-Object { $_.Groups[1].Value } | Sort-Object -Unique
$lmiss = $labels | Where-Object { $ids -notcontains $_ }
if ($lmiss) {
  $resultados += "ERRO labels sem alvo: " + ($lmiss -join ', ')
} else {
  $resultados += "OK  labels ($($labels.Count)) todas com alvo"
}

# 4) conflito classe 'hidden' x atributo em elementos alternados via .hidden=
$toggled = @('planChip','scanIdle','scanLoading','scanDone','scanPreview','chatPanel',
             'screen-inicio','screen-checkin','screen-suporte')
$conflict = @()
foreach ($id in $toggled) {
  $mm = [regex]::Match($h, "<[^>]*id=`"$id`"[^>]*>")
  if ($mm.Success) {
    if ($mm.Value -match '\shidden[\s>"]') { $conflict += $id }
  }
}
if ($conflict) {
  $resultados += "ERRO conflito classe/atributo hidden: " + ($conflict -join ', ')
} else {
  $resultados += "OK  nenhum conflito classe x atributo hidden"
}

# 5) balanceamento JS (ignora strings, comentarios; nao trata regex)
$m = [regex]::Matches($h, '(?s)<script>(.*?)</script>')
$js = $m[$m.Count - 1].Groups[1].Value
$stack = New-Object System.Collections.Stack
$pairs = @{ '{' = '}'; '(' = ')'; '[' = ']' }
$closing = @{ '}' = '{'; ')' = '('; ']' = '[' }
$line = 1
$i = 0
$state = 'code'
$err = $null
while ($i -lt $js.Length -and -not $err) {
  $c = $js[$i]
  if ($c -eq "`n") { $line++ }
  switch ($state) {
    'code' {
      if ($c -eq '/' -and $i + 1 -lt $js.Length -and $js[$i + 1] -eq '/') {
        $state = 'line'; $i++
      } elseif ($c -eq '/' -and $i + 1 -lt $js.Length -and $js[$i + 1] -eq '*') {
        $state = 'block'; $i++
      } elseif ($c -eq "'") { $state = 'sq' }
      elseif ($c -eq '"') { $state = 'dq' }
      elseif ($c -eq '`') { $state = 'tpl' }
      elseif ($pairs.ContainsKey("$c")) { [void]$stack.Push(@{ c = "$c"; line = $line }) }
      elseif ($closing.ContainsKey("$c")) {
        if ($stack.Count -eq 0) {
          $err = "linha ${line}: '$c' fecha sem abrir"
        } elseif ($stack.Peek().c -ne $closing["$c"]) {
          $err = "linha ${line}: '$c' nao fecha '$($stack.Peek().c)' (linha $($stack.Peek().line))"
        } else {
          [void]$stack.Pop()
        }
      }
    }
    'line'   { if ($c -eq "`n") { $state = 'code' } }
    'block'  { if ($c -eq '*' -and $i + 1 -lt $js.Length -and $js[$i + 1] -eq '/') { $state = 'code'; $i++ } }
    'sq'     { if ($c -eq '\') { $i++ } elseif ($c -eq "'") { $state = 'code' } }
    'dq'     { if ($c -eq '\') { $i++ } elseif ($c -eq '"') { $state = 'code' } }
    'tpl'    { if ($c -eq '\') { $i++ } elseif ($c -eq '`') { $state = 'code' } }
  }
  $i++
}
if ($err) {
  $resultados += "ERRO JS: $err"
} elseif ($stack.Count -gt 0) {
  $pend = ($stack | ForEach-Object { "$($_.c)@$($_.line)" }) -join ', '
  $resultados += "ERRO JS: $($stack.Count) delimitador(es) nao fechado(s): $pend"
} else {
  $resultados += "OK  JS balanceado ($line linhas, estado final '$state')"
}

# 6) handlers duplicados em el.*
$handlers = [regex]::Matches($js, "el\.(\w+)\.addEventListener\('(\w+)'") |
  ForEach-Object { "$($_.Groups[1].Value).$($_.Groups[2].Value)" }
$dh = $handlers | Group-Object | Where-Object { $_.Count -gt 1 }
if ($dh) {
  $resultados += "ERRO handlers duplicados: " + (($dh | ForEach-Object { "$($_.Name) x$($_.Count)" }) -join ', ')
} else {
  $resultados += "OK  handlers ($($handlers.Count)) sem duplicatas"
}

# 7) referencias a el.xxx que nao existem no objeto el
$elProps = [regex]::Matches($js, '^\s{2}(\w+):\s*\$\(', 'Multiline') |
  ForEach-Object { $_.Groups[1].Value } | Sort-Object -Unique
$used = [regex]::Matches($js, 'el\.(\w+)') | ForEach-Object { $_.Groups[1].Value } | Sort-Object -Unique
$noEl = $used | Where-Object { $elProps -notcontains $_ }
if ($noEl) {
  $resultados += "ERRO el.* sem definicao: " + ($noEl -join ', ')
} else {
  $resultados += "OK  el.* ($($used.Count) props) todas definidas"
}

# 8) select/option balanceados (so tags reais)
$selOpen = ([regex]::Matches($h, '<select\s+id=')).Count
$selClose = ([regex]::Matches($h, '</select>')).Count
$optOpen = ([regex]::Matches($h, '<option[ >]')).Count
$optClose = ([regex]::Matches($h, '</option>')).Count
if ($selOpen -eq $selClose -and $optOpen -eq $optClose) {
  $resultados += "OK  select $selOpen/$selClose | option $optOpen/$optClose"
} else {
  $resultados += "ERRO tags select $selOpen/$selClose option $optOpen/$optClose"
}

$f = Get-Item $Arquivo
$resultados += "INFO tamanho: $([math]::Round($f.Length / 1KB, 1)) KB | modificado: $($f.LastWriteTime)"

$resultados

param([string]$Arquivo)

$h = Get-Content -Raw $Arquivo

# Elementos alternados via JS: el.X.hidden = true/false  -> exigem ATRIBUTO, proibem classe 'hidden'
$viaProp = @('planChip','scanIdle','scanLoading','scanDone','scanPreview','chatPanel',
             'screen-inicio','screen-checkin','screen-suporte')

# Elementos alternados via classList -> exigem CLASSE 'hidden', proibem atributo
$viaClass = @('inertiaModal','callOverlay')

function AnalisarTag([string]$html, [string]$id) {
  $mm = [regex]::Match($html, "<[^>]*\bid=`"$id`"[^>]*>")
  if (-not $mm.Success) { return @{ achou = $false } }
  $tag = $mm.Value

  # atributo hidden solto? casa ' hidden' que NAO esta dentro de class="..."
  $classM = [regex]::Match($tag, '\bclass="([^"]*)"')
  $classVal = if ($classM.Success) { $classM.Groups[1].Value } else { '' }
  $hasClassHidden = ($classVal -split '\s+') -contains 'hidden'

  # remove o trecho class="..." e procura 'hidden' como atributo
  $resto = $tag
  if ($classM.Success) { $resto = $tag.Replace($classM.Value, '') }
  $hasAttrHidden = ($resto -match '(^|\s)hidden(\s|>|$)')

  return @{ achou = $true; classe = $hasClassHidden; attr = $hasAttrHidden; tag = $tag }
}

$out = @()

$erros = 0
foreach ($id in $viaProp) {
  $r = AnalisarTag $h $id
  if (-not $r.achou) { $out += "ERRO [$id] tag nao encontrada"; $erros++; continue }
  if ($r.classe) { $out += "ERRO [$id] tem CLASSE 'hidden' mas JS usa .hidden= (nunca abre)"; $erros++ }
  elseif (-not $r.attr -and $id -ne 'scanIdle' -and $id -ne 'screen-inicio') {
    $out += "ERRO [$id] sem ATRIBUTO hidden (JS usa .hidden=; sem attr nao esconde)"; $erros++
  } else { $out += "OK   [$id] usa atributo (sem classe conflitante)" }
}

foreach ($id in $viaClass) {
  $r = AnalisarTag $h $id
  if (-not $r.achou) { $out += "ERRO [$id] tag nao encontrada"; $erros++; continue }
  if ($r.attr) { $out += "ERRO [$id] tem ATRIBUTO hidden mas JS usa classList('hidden')"; $erros++ }
  elseif (-not $r.classe) { $out += "ERRO [$id] sem CLASSE 'hidden' inicial"; $erros++ }
  else { $out += "OK   [$id] usa classe (sem atributo conflitante)" }
}

$out
""
if ($erros -eq 0) { "RESULTADO: OK - nenhum conflito classe/atributo" }
else { "RESULTADO: $erros ERRO(S) de conflito" }

