function aplicarPlano(nome) {
  if (!nome) return;
  const alvo = String(nome).trim();

  // Match tolerante: ignora acentos/caixa ("SulAmérica" vs "sulamerica").
  const norm = (s) => s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const alvoN = norm(alvo);

  // 1) igualdade exenta (normalizada); 2) casamento por contenção nos dois
  //    sentidos — resolve "particular" vs opção "Particular (sem plano)".
  let opt = Array.from(el.fPlano.options).find(o => norm(o.value) === alvoN);
  if (!opt) {
    opt = Array.from(el.fPlano.options).find(o => {
      const v = norm(o.value);
      return v !== '' && (v.includes(alvoN) || alvoN.includes(v));
    });
  }

  if (!opt) {
    // Valor vindo do OCR que não está no catálogo → cria dinamicamente.
    const display = alvo.replace(/\b\w/g, c => c.toUpperCase()); // "unimed" → "Unimed"
    opt = new Option(display, display);
    el.fPlano.add(opt);
  }

  el.fPlano.value = opt.value;
  refreshConfirm();
  updatePlanChip();
}

