# 4) conflito classe 'hidden' x atributo em elementos alternados via .hidden=
#    ATENÇÃO: precisa separar token de class="..." do atributo solto `hidden`,
#    senão dá falso positivo em quem usa o atributo corretamente.
$toggled = @('planChip','scanIdle','scanLoading','scanDone','scanPreview','chatPanel',
             'screen-inicio','screen-checkin','screen-suporte')
$conflict = @()
foreach ($id in $toggled) {
  $mm = [regex]::Match($h, "<[^>]*\bid=`"$id`"[^>]*>")
  if (-not $mm.Success) { continue }
  $tag = $mm.Value
  $classM = [regex]::Match($tag, '\bclass="([^"]*)"')
  $classVal = if ($classM.Success) { $classM.Groups[1].Value } else { '' }
  $hasClassHidden = ($classVal -split '\s+') -contains 'hidden'
  if ($hasClassHidden) { $conflict += "$id (classe hidden + JS usa .hidden=)" }
}
if ($conflict) {
  $resultados += "ERRO conflito classe/atributo hidden: " + ($conflict -join ', ')
} else {
  $resultados += "OK  nenhum conflito classe x atributo hidden"
}

