input.command:
$h = Get-Content -Raw 'fluxo-dual.html'
$m = [regex]::Matches($h, '(?s)<script>(.*?)</script>')
$js = $m[$m.Count-1].Groups[1].Value

# Declaracoes de topo (const/let/var/function) - procura DUPLICADAS
$decls = @()
foreach ($re in @('(?m)^\s*const\s+(\w+)\s*=', '(?m)^\s*let\s+(\w+)\s*=', '(?m)^\s*var\s+(\w+)\s*=', '(?m)^\s*function\s+(\w+)\s*\(')) {
  foreach ($mm in [regex]::Matches($js, $re)) { $decls += $mm.Groups[1].Value }
}
$dup = $decls | Group-Object | Where-Object { $_.Count -gt 1 }
if ($dup) { "DUPLICADAS: " + (($dup | ForEach-Object { "$($_.Name) x$($_.Count)" }) -join ', ') } else { "OK: $($decls.Count) declaracoes de topo, sem duplicatas" }

# Estado do objeto state
$stateBlock = [regex]::Match($js, 'const state = \{[\s\S]*?\};').Value
foreach ($k in @('chatOpen','chatBooted','docScanned','scanning','inertiaModalOpen','screen','ticket','previewUrl','inertiaTimer','lastInertiaReason')) {
  if ($stateBlock -match "\b$k\s*:") { "state.$k OK" } else { "state.$k FALTA" }
}

# Todas as funcoes chamadas sem declaracao conhecida (amostra das do chat)
foreach ($f in @('openChat','closeChat','sendChat','addBubble','renderChips','showTyping','escalateFromChat','escapeHtml','renderRich','currentPlano','aplicarPlano','refreshConfirm','updatePlanChip','stopInertia','startInertia','bumpInertia','showToast','goTo','resetScanUI','runOcr','openCapture')) {
