# Servidor HTTP estatico minimo (sem Node/Python) para testar a PoC no navegador.
$root = 'C:\Users\pedro.silva\Documents\Default Project'
$port = 8765

$listener = New-Object System.Net.Sockets.TcpListener([System.Net.IPAddress]::Loopback, $port)
$listener.Start()
Write-Output "LISTENING http://localhost:$port/ -> $root"

function Get-ContentType([string]$ext) {
  switch ($ext) {
    '.html' { 'text/html; charset=utf-8' }
    '.js'   { 'text/javascript; charset=utf-8' }
    '.css'  { 'text/css; charset=utf-8' }
    '.json' { 'application/json; charset=utf-8' }
    '.svg'  { 'image/svg+xml' }
    '.png'  { 'image/png' }
    '.ico'  { 'image/x-icon' }
    default { 'application/octet-stream' }
  }
}

$allowed = @('.html', '.js', '.css', '.json', '.svg', '.png', '.ico')

while ($true) {
  $client = $listener.AcceptTcpClient()
  try {
    $stream = $client.GetStream()
    $buf = New-Object byte[] 16384
    $read = $stream.Read($buf, 0, $buf.Length)
    if ($read -le 0) { continue }

    $req = [System.Text.Encoding]::UTF8.GetString($buf, 0, $read)
    $first = ($req -split "`r?`n")[0]
    $parts = $first -split ' '
    $rawPath = if ($parts.Length -ge 2) { $parts[1] } else { '/' }
    $rawPath = [System.Uri]::UnescapeDataString($rawPath)
    if ($rawPath -eq '/' -or $rawPath -eq '') { $rawPath = '/fluxo-dual.html' }

    $rel = ($rawPath -replace '/', '\').TrimStart('\')
    $full = [System.IO.Path]::GetFullPath((Join-Path $root $rel))
    $ext = [System.IO.Path]::GetExtension($full).ToLower()

    if ($full.StartsWith($root, [System.StringComparison]::OrdinalIgnoreCase) -and
        $allowed -contains $ext -and
        (Test-Path -LiteralPath $full -PathType Leaf)) {

      $bytes = [System.IO.File]::ReadAllBytes($full)
      $hdr = "HTTP/1.1 200 OK`r`n" +
             "Content-Type: " + (Get-ContentType $ext) + "`r`n" +
             "Content-Length: $($bytes.Length)`r`n" +
             "Cache-Control: no-store`r`n" +
             "Connection: close`r`n`r`n"
      $hb = [System.Text.Encoding]::ASCII.GetBytes($hdr)
      $stream.Write($hb, 0, $hb.Length)
      $stream.Write($bytes, 0, $bytes.Length)
    }
    else {
      $body = [System.Text.Encoding]::UTF8.GetBytes('404 Not Found')
      $hdr = "HTTP/1.1 404 Not Found`r`nContent-Type: text/plain; charset=utf-8`r`n" +
             "Content-Length: $($body.Length)`r`nConnection: close`r`n`r`n"
      $hb = [System.Text.Encoding]::ASCII.GetBytes($hdr)
      $stream.Write($hb, 0, $hb.Length)
      $stream.Write($body, 0, $body.Length)
    }
    $stream.Flush()
  }
  catch { }
  finally { $client.Close() }
}

