<script>
(function () {
  var R = { errors: (window.__ERR || []), steps: [] };
  var sleep = function (ms) { return new Promise(function (r) { setTimeout(r, ms); }); };
  function $(id) { return document.getElementById(id); }
  function step(n, fn) { try { R.steps.push('OK    ' + n + ' = ' + fn()); } catch (e) { R.steps.push('THREW ' + n + ' -> ' + e.message); } }
  function hit(id) {
    var el = $(id); if (!el) return 'elemento inexistente';
    var r = el.getBoundingClientRect();
    var cx = r.left + r.width / 2, cy = r.top + r.height / 2;
    if (r.width === 0 || r.height === 0) return 'RETANGULO ZERADO ' + Math.round(r.width) + 'x' + Math.round(r.height);
    var top = document.elementFromPoint(cx, cy);
    if (!top) return 'elementFromPoint=null (fora da viewport)';
    var chain = [], n = top;
    while (n && n !== document.body && chain.length < 4) { chain.push(n.tagName + (n.id ? '#' + n.id : '') + (n.className && typeof n.className === 'string' ? '.' + n.className.split(' ').slice(0,3).join('.') : '')); n = n.parentElement; }
    return (el.contains(top) || top.contains(el) ? 'OK' : 'BLOQUEADO por ') + ' | top=' + chain.join(' < ');
  }

  (async function () {
    await sleep(400);
    step('viewport', function () { return window.innerWidth + 'x' + window.innerHeight; });
    step('app height vs viewport', function () {
      var a = $('app');
      return 'app=' + Math.round(a.getBoundingClientRect().height) + ' doc=' + document.documentElement.scrollHeight + ' viewport=' + window.innerHeight;
    });
    step('scrollY inicial', function () { return window.scrollY; });

    step('HIT btnOpenChat', function () { return hit('btnOpenChat'); });
    step('HIT btnIaLink',   function () { return hit('btnIaLink'); });
    step('HIT btnRota1',    function () { return hit('btnRota1'); });
    step('HIT btnRota2',    function () { return hit('btnRota2'); });

    // ---- chat pela Tela 1 ----
    $('btnIaLink').click();
    await sleep(80);
    step('chat abriu', function () { return String($('chatPanel').hidden); });
    step('chat geometry', function () {
      var p = $('chatPanel').getBoundingClientRect();
      var f = $('chatForm').getBoundingClientRect();
      var i = $('chatInput').getBoundingClientRect();
      return 'painel y=' + Math.round(p.y) + ' h=' + Math.round(p.height) +
             ' | formBottom=' + Math.round(f.bottom) + ' | input y=' + Math.round(i.y) + ' h=' + Math.round(i.height) +
             ' | viewportH=' + window.innerHeight +
             ' | INPUT VISIVEL=' + (i.top >= 0 && i.bottom <= window.innerHeight);
    });
    step('HIT chatInput', function () { return hit('chatInput'); });
    step('HIT chatSend',  function () { return hit('chatSend'); });

    // Enter deve enviar
    $('chatInput').value = 'onde fica a sala de espera';
    $('chatSend').click();
    await sleep(200);
    step('bubbles apos botao enviar', function () { return $('chatMessages').children.length; });
    await sleep(3000);
    step('chat ainda aberto apos 3s', function () { return String(!$('chatPanel').hidden); });
    step('inertia modal aberto com chat?', function () { return !$('inertiaModal').classList.contains('hidden'); });
    $('chatClose').click();
    await sleep(40);

    // ---- Tela 4 via Rota 2 ----
    $('btnRota2').click();
    await sleep(2500);
    step('rota2 -> screen', function () { return state.screen; });
    step('ticketChip', function () { return $('ticketChip').textContent; });
    step('HIT btnChat na tela 4', function () { return hit('btnChat'); });
    $('btnChat').click();
    await sleep(80);
    step('chat tela 4 abriu', function () { return String($('chatPanel').hidden); });
    step('chat tela4 geometry', function () {
      var i = $('chatInput').getBoundingClientRect();
      return 'inputBottom=' + Math.round(i.bottom) + ' viewportH=' + window.innerHeight + ' VISIVEL=' + (i.top >= 0 && i.bottom <= window.innerHeight);
    });
    $('chatClose').click();
    await sleep(40);

    // ---- inercia: volta ao inicio e espera 11s ----
    $('btnReiniciar').click();
    await sleep(60);
    step('reiniciar -> screen', function () { return state.screen; });
    step('modal inercia antes de 10s', function () { return !$('inertiaModal').classList.contains('hidden'); });
    await sleep(11500);
    step('modal inercia apos 11.5s', function () { return !$('inertiaModal').classList.contains('hidden'); });
    step('HIT btnIaLink com modal aberto', function () { return hit('btnIaLink'); });

    var payload = JSON.stringify(R).replace(/</g, '\\u003c');
    document.body.insertAdjacentHTML('beforeend', '<div id="__TEST2__">' + payload + '</div>');
    document.documentElement.setAttribute('data-test-done2', '1');
  })();
})();
</script>
