/* --------------------------------------------------------------
   ESCOLHA DO TIPO DE ATENDIMENTO (Tela 1): consulta x pronto-socorro.
   O estado é exposto em `aria-pressed`, então o CSS abaixo é a ÚNICA
   fonte de estilo do selecionado — nada de classes geradas em runtime
   pelo CDN do Tailwind (que podem não existir quando o clique ocorre).
   -------------------------------------------------------------- */
.tipo-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  padding: 14px 8px;
  border: 2px solid #cbd5e1;
  border-radius: 18px;
  background: #fff;
  color: #334155;
  font-size: 13.5px;
  font-weight: 800;
  line-height: 1.15;
  text-align: center;
  cursor: pointer;
  transition: transform .12s ease, border-color .15s ease,
              background-color .15s ease, box-shadow .15s ease;
}
.tipo-btn .tipo-emoji { font-size: 26px; line-height: 1; }
.tipo-btn:hover { background: #f8fafc; }
.tipo-btn:active { transform: scale(.97); }
.tipo-btn:focus-visible { outline: none; box-shadow: 0 0 0 4px #5EEAD4; }

.tipo-btn[aria-pressed="true"] {
  border-color: #0F766E;
  background: #0F766E;
  color: #fff;
  box-shadow: 0 10px 20px -8px rgba(15, 118, 110, .55);
}
.tipo-btn[aria-pressed="true"]:hover { background: #115E59; }

/* Pronto-socorro fica VERMELHO quando selecionado (urgência visual). */
#tipoPronto[aria-pressed="true"] {
  border-color: #b91c1c;
  background: #b91c1c;
  box-shadow: 0 10px 20px -8px rgba(185, 28, 28, .55);
}
#tipoPronto[aria-pressed="true"]:hover { background: #991b1b; }

/* A Rota 1 muda de sentido em urgência: botão vermelho + sem escaneamento. */
#btnRota1[data-urgente="1"] {
  background: #b91c1c;
  border-color: #b91c1c;
  box-shadow: 0 14px 28px -12px rgba(185, 28, 28, .7);
}
#btnRota1[data-urgente="1"]:hover { background: #991b1b; }

/* Chips da Tela 4: prioridade ALTA e tipo de atendimento. */
