/* --------------------------------------------------------------------------
   6. TELA 1 — ESCOLHA DO ATENDIMENTO + A DUPLA ROTA
   -------------------------------------------------------------------------- */

/**
 * setTipo('consulta' | 'pronto') — define o tipo de atendimento.
 *
 * Consequências do PRONTO-SOCORRO (urgência):
 *   1. o aviso vermelho de prioridade aparece;
 *   2. a Rota 1 deixa de ser "escanear documento" e vira "ir direto à
 *      triagem" — em urgência ninguém deve perder tempo preenchendo algo;
 *   3. o chamado sai como PRIORIDADE ALTA e a Tela 4 exibe o chip vermelho.
 *
 * NOTA: o estilo do selecionado vive no CSS (.tipo-btn[aria-pressed="true"]),
 * então aqui só mexemos em atributo/texto — nunca em classes dinâmicas.
 */
function setTipo(tipo) {
  const pronto = tipo === 'pronto';
  const anterior = state.tipoAtendimento;
  state.tipoAtendimento = pronto ? 'pronto' : 'consulta';

  // Botões de escolha (estado exposto para leitores de tela).
  el.tipoConsulta.setAttribute('aria-pressed', String(!pronto));
  el.tipoPronto.setAttribute('aria-pressed', String(pronto));

  // Aviso de urgência (usa ATRIBUTO hidden — igual a planChip/chatPanel).
  el.tipoUrgente.hidden = !pronto;

  el.tipoHint.textContent = pronto
    ? 'Urgência · você vai direto à triagem.'
    : 'Atendimento com hora marcada · prioridade normal.';

  // A Rota 1 muda de sentido em urgência (sem escaneamento).
  el.btnRota1.dataset.urgente = pronto ? '1' : '0';
  el.rota1Icon.textContent    = pronto ? '🚑' : '🚀';
  el.rota1Label.textContent   = pronto ? 'Ir direto à triagem' : 'Fazer sozinho (Rápido)';
  el.descRota1.textContent    = pronto
    ? 'Registro automático, sem formulário · prioridade ALTA.'
    : 'Escaneie seu documento e finalize em segundos.';

  if (anterior !== state.tipoAtendimento) {
    analyticsService.track('service_type_selected', { tipo: state.tipoAtendimento });
  }
}

el.tipoConsulta.addEventListener('click', () => setTipo('consulta'));
el.tipoPronto.addEventListener('click', () => setTipo('pronto'));

/**
 * chamarRecepcao(reason) — emite o chamado humano e leva à Tela 4.
 * Caminho compartilhado pela Rota 2 e pelo atalho de urgência da Rota 1.
 * PONTO DE INTEGRAÇÃO REAL: o `reason` vira o payload de triagem
 * ({ priority: state.tipoAtendimento === 'pronto' ? 'ALTA' : 'NORMAL' }).
 * @param {string} reason — motivo/report auditável do chamado
 */
async function chamarRecepcao(reason) {
  // 1) Overlay "Chamando recepção…" (feedback imediato = percepção de velocidade)
  el.callOverlay.classList.remove('hidden');
  el.callOverlay.classList.add('flex');
  el.statusText.textContent = 'Chamando recepção…';

  // 2) Dispara o chamado no sistema de fila (aqui: simulado ~1.6s)
  const res = await queueService.dispatch(reason);
  await new Promise(r => setTimeout(r, 1600));

  // 3) Esconde overlay e segue para a Tela 4 (Sucesso / Suporte acionado)
  el.callOverlay.classList.add('hidden');
  el.callOverlay.classList.remove('flex');

  state.ticket = res.ticket;
  goTo('suporte');
}

el.btnRota1.addEventListener('click', async () => {
  // PRONTO-SOCORRO: pula o check-in e vai direto à triagem (prioridade ALTA).
  if (state.tipoAtendimento === 'pronto') {
    analyticsService.track('route_selected', { route: 'autonomous_urgent' });
    await chamarRecepcao('PRONTO_SOCORRO_SELF');
    return;
  }
  analyticsService.track('route_selected', { route: 'autonomous' });
  goTo('checkin');
});

/** ROTA 2: chamado humano imediato — overlay visual → Tela de sucesso. */
el.btnRota2.addEventListener('click', async () => {
  analyticsService.track('route_selected', { route: 'human' });
  await chamarRecepcao('ROTA_2_HUMAN_BUTTON');
});

