<script>
(function () {
  var R = { errors: (window.__ERR || []), steps: [], fail: 0 };
  var sleep = function (ms) { return new Promise(function (r) { setTimeout(r, ms); }); };
  function $(id) { return document.getElementById(id); }
  function chk(name, got, want) {
    var ok = String(got) === String(want);
    if (!ok) R.fail++;
    R.steps.push((ok ? 'PASS ' : 'FAIL ') + name + ' -> "' + got + '"' + (ok ? '' : ' (esperado: "' + want + '")'));
  }
  function info(name, v) { R.steps.push('      ' + name + ' = ' + v); }
  function hit(id) {
    var el = $(id); if (!el) return 'elemento inexistente';
    var r = el.getBoundingClientRect();
    var top = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
    if (!top) return 'null (fora da viewport)';
    return (el.contains(top) || top.contains(el)) ? 'OK' : 'BLOQUEADO por ' + top.tagName + '#' + top.id;
  }
  function chatInputVisivel() {
    var i = $('chatInput').getBoundingClientRect();
    var s = $('chatSend').getBoundingClientRect();
    var vis = (i.top >= 0 && i.bottom <= window.innerHeight) && (s.top >= 0 && s.bottom <= window.innerHeight);
    return vis ? 'true' : 'false (inputBottom=' + Math.round(i.bottom) + ' sendBottom=' + Math.round(s.bottom) + ' vh=' + window.innerHeight + ')';
  }
  function ultimaBolha() {
    var c = $('chatMessages').children;
    return c.length ? c[c.length - 1].textContent : '';
  }

  (async function () {
    await sleep(400);
    stopInertia(); // congela a inercia enquanto montamos o cenario

