    info('app/doc/vp', Math.round($('app').getBoundingClientRect().height) + '/' +
         document.documentElement.scrollHeight + '/' + window.innerHeight);
    chk('estado inicial', state.tipoAtendimento, 'consulta');
    chk('aviso urgencia escondido no inicio', String($('tipoUrgente').hidden), 'true');
    chk('rota1 label padrao', $('rota1Label').textContent, 'Fazer sozinho (Rapido)'.replace('Rapido','Rápido'));
