    chk('HIT tipoPronto', hit('tipoPronto'), 'OK');
    chk('HIT btnIaLink', hit('btnIaLink'), 'OK');
    chk('aria-pressed consulta', $('tipoConsulta').getAttribute('aria-pressed'), 'true');

    // seleciona PRONTO-SOCORRO
    $('tipoPronto').click();
    await sleep(50);
    chk('state apos clicar pronto', state.tipoAtendimento, 'pronto');
    chk('aria-pressed pronto', $('tipoPronto').getAttribute('aria-pressed'), 'true');
    chk('aria-pressed consulta solto', $('tipoConsulta').getAttribute('aria-pressed'), 'false');
    chk('aviso urgencia visivel', String($('tipoUrgente').hidden), 'false');
    chk('rota1 label urgence', $('rota1Label').textContent, 'Ir direto à triagem');
    chk('rota1 data-urgente', $('btnRota1').dataset.urgente, '1');
    info('dica', $('tipoHint').textContent);
    info('rota1 desc', $('descRota1').textContent);

    // ===== CHAT NA TELA 1 (correcao de ancoragem) =====
