    chk('chatInput visivel (Tela 1)', chatInputVisivel(), 'true');
    chk('HIT chatInput (Tela 1)', hit('chatInput'), 'OK');
    chk('bubbles de boas-vindas', $('chatMessages').children.length, 1);
    chk('chips', $('chatChips').children.length, 6);

    // IA troca o tipo de atendimento pela conversa
