input.content:
(function () {
  var R = { errors: (window.__ERR || []), steps: [], fail: 0 };
  var sleep = function (ms) { return new Promise(function (r) { setTimeout(r, ms); }); };
  function $(id) { return document.getElementById(id); }
  function chk(name, got, want) {
    var ok = String(got) === String(want);
    if (!ok) R.fail++;
    R.steps.push((ok ? 'PASS ' : 'FAIL ') + name + ' -> "' + got + '"' + (ok ? '' : ' (esperado: "' + want + '")'));
  }
  function info(name, v) { R.steps.push('      ' + name + ' = ' + v); }
  function hit(id) {
    var el = $(id);
    if (!el) return 'elemento inexistente';
    var r = el.getBoundingClientRect();
    if (r.top < 0 || r.bottom > window.innerHeight) {
      el.scrollIntoView({ block: 'center' });
      r = el.getBoundingClientRect();
    }
    var top = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
    if (!top) return 'null (fora da viewport)';
    return (el.contains(top) || top.contains(el)) ? 'OK' : 'BLOQUEADO por ' + top.tagName + '#' + top.id;
  }
  function chatInputVisivel() {
    var i = $('chatInput').getBoundingClientRect();
    var s = $('chatSend').getBoundingClientRect();
    var vis = (i.top >= 0 && i.bottom <= window.innerHeight) && (s.top >= 0 && s.bottom <= window.innerHeight);
    return vis ? 'true'
      : 'false (inputBottom=' + Math.round(i.bottom) + ' sendBottom=' + Math.round(s.bottom) + ' vh=' + window.innerHeight + ')';
  }
  function ultimaBolha() {
    var c = $('chatMessages').children;
    return c.length ? c[c.length - 1].textContent : '';
  }

  (async function () {
    await sleep(400);
    stopInertia(); // congela a inércia enquanto montamos o cenário

    // ===== TELA 1: escolha do tipo de atendimento =====
    info('viewport', window.innerWidth + 'x' + window.innerHeight);
    info('app/doc/vp', Math.round($('app').getBoundingClientRect().height) + '/' +
      document.documentElement.scrollHeight + '/' + window.innerHeight);
    info('y do btnIaLink', Math.round($('btnIaLink').getBoundingClientRect().top));
    info('y do btnRota1', Math.round($('btnRota1').getBoundingClientRect().top));

    chk('estado inicial', state.tipoAtendimento, 'consulta');
    chk('aviso urgência escondido no início', String($('tipoUrgente').hidden), 'true');
    chk('rótulo padrão da rota 1', $('rota1Label').textContent, 'Fazer sozinho (Rápido)');
    chk('HIT tipoConsulta', hit('tipoConsulta'), 'OK');
    chk('HIT tipoPronto', hit('tipoPronto'), 'OK');
    chk('HIT btnIaLink', hit('btnIaLink'), 'OK');
    chk('aria-pressed consulta', $('tipoConsulta').getAttribute('aria-pressed'), 'true');

    // seleciona PRONTO-SOCORRO
    $('tipoPronto').click();
    await sleep(50);
    chk('state após clicar pronto', state.tipoAtendimento, 'pronto');
    chk('aria-pressed pronto', $('tipoPronto').getAttribute('aria-pressed'), 'true');
    chk('aria-pressed consulta solto', $('tipoConsulta').getAttribute('aria-pressed'), 'false');
    chk('aviso urgência visível', String($('tipoUrgente').hidden), 'false');
    chk('rótulo da rota 1 em urgência', $('rota1Label').textContent, 'Ir direto à triagem');
    chk('rota1 data-urgente', $('btnRota1').dataset.urgente, '1');
    info('dica', $('tipoHint').textContent);
    info('desc da rota 1', $('descRota1').textContent);

    // ===== CHAT NA TELA 1 (correção de ancoragem) =====
    $('btnIaLink').click();
    await sleep(80);
    chk('chat abriu (Tela 1)', String($('chatPanel').hidden), 'false');
    chk('chatInput visível (Tela 1)', chatInputVisivel(), 'true');
    chk('HIT chatInput (Tela 1)', hit('chatInput'), 'OK');
    chk('bolhas de boas-vindas', $('chatMessages').children.length, 1);
    chk('chips', $('chatChips').children.length, 6);

    // IA troca o tipo de atendimento pela conversa
    $('tipoConsulta').click();
    await sleep(30);
    $('chatInput').value = 'quero ir no pronto-socorro';
    $('chatSend').click();
    await sleep(3000);
    chk('IA trocou para pronto', state.tipoAtendimento, 'pronto');
    info('resposta IA (troca)', ultimaBolha().slice(0, 70));

    $('chatInput').value = 'como funciona o pronto-socorro?';
    $('chatSend').click();
    await sleep(3000);
    info('resposta IA (explicação)', ultimaBolha().slice(0, 70));
    chk('IA citou PRIORIDADE ALTA', ultimaBolha().indexOf('PRIORIDADE ALTA') >= 0, 'true');

    // SEGURANÇA CLÍNICA: sintoma nunca recebe orientação da IA
    $('chatInput').value = 'dor forte no peito';
    $('chatSend').click();
    await sleep(3000);
    info('resposta IA (sintoma)', ultimaBolha().slice(0, 70));
    chk('IA escalou para SAMU 192', ultimaBolha().indexOf('192') >= 0, 'true');
    chk('inércia não abriu com chat aberto', String($('inertiaModal').classList.contains('hidden')), 'true');

    $('chatClose').click();
    await sleep(40);
    chk('chat fechou', String($('chatPanel').hidden), 'true');

    // ===== ROTA 1 EM URGÊNCIA: pula o check-in =====
    chk('rota 1 segue em urgência', $('rota1Label').textContent, 'Ir direto à triagem');
    $('btnRota1').click();
    await sleep(2600);
    chk('rota1 (pronto) levou a', state.screen, 'suporte');
    info('ticketChip', $('ticketChip').textContent);
    chk('ticketChip tem PRIORIDADE ALTA', $('ticketChip').textContent.indexOf('PRIORIDADE ALTA') >= 0, 'true');
    chk('ticketChip data-prio', $('ticketChipWrap').dataset.prio, 'alta');
    chk('tipoChip visível', String($('tipoChip').hidden), 'false');
    chk('tipoChip data-tipo', $('tipoChip').dataset.tipo, 'pronto');
    info('tipoChip', $('tipoChipIcon').textContent + ' ' + $('tipoChipText').textContent);

    // ===== CHAT NA TELA 4 (antes: input ficava abaixo da dobra) =====
    $('btnChat').click();
    await sleep(80);
    chk('chat abriu (Tela 4)', String($('chatPanel').hidden), 'false');
    chk('chatInput visível (Tela 4)', chatInputVisivel(), 'true');
    chk('HIT chatInput (Tela 4)', hit('chatInput'), 'OK');
    $('chatInput').value = 'onde fica a sala de espera';
    $('chatSend').click();
    await sleep(3000);
    chk('IA respondeu sala', ultimaBolha().indexOf('sala') >= 0, 'true');
    $('chatClose').click();
    await sleep(40);

    // ===== VOLTA E FLUXO NORMAL DE CONSULTA =====
    $('btnReiniciar').click();
    await sleep(60);
    stopInertia();
    chk('reiniciar -> início', state.screen, 'inicio');
    $('tipoConsulta').click();
    await sleep(40);
    chk('voltou para consulta', state.tipoAtendimento, 'consulta');
    chk('rótulo da rota 1 restaurado', $('rota1Label').textContent, 'Fazer sozinho (Rápido)');
    chk('rota1 data-urgente', $('btnRota1').dataset.urgente, '0');
    chk('aviso urgência escondido', String($('tipoUrgente').hidden), 'true');
    chk('HIT btnRota1', hit('btnRota1'), 'OK');

    $('btnRota1').click();
    await sleep(60);
    chk('rota1 (consulta) levou a', state.screen, 'checkin');
    $('btnScan').click();
    await sleep(3200);
    chk('OCR nome', $('fNome').value, 'Maria Silva');
    chk('OCR plano', $('fPlano').value, 'Saúde Total');
    chk('OCR consulta', $('fConsulta').value, '14:30 com Dr. Carlos');
    chk('confirmar liberado', String($('btnConfirmar').disabled), 'false');
    $('btnConfirmar').click();
    await sleep(1400);
    chk('confirmar voltou para', state.screen, 'inicio');

    // ===== ROTA 2 e INÉRCIA =====
    $('tipoConsulta').click();
    await sleep(30);
    $('btnRota2').click();
    await sleep(2600);
    chk('rota2 levou a', state.screen, 'suporte');
    chk('ticketChip prioridade normal', $('ticketChipWrap').dataset.prio, 'normal');
    chk('tipoChip consulta', $('tipoChipText').textContent, 'Consulta médica');
    $('btnReiniciar').click();
    await sleep(60);
    chk('inércia não disparou antes dos 10s', String($('inertiaModal').classList.contains('hidden')), 'true');
    startInertia();
    await sleep(11500);
    chk('inércia disparou após 11.5s', String($('inertiaModal').classList.contains('hidden')), 'false');
    $('inertiaNo').click();
    await sleep(60);
    chk('inércia fechou', String($('inertiaModal').classList.contains('hidden')), 'true');

    info('erros de JS', R.errors.length ? R.errors.join(' || ') : '(nenhum)');
    if (R.errors.length) R.fail += R.errors.length;

    var payload = JSON.stringify(R).replace(/</g, '\\u003c');
    document.body.insertAdjacentHTML('beforeend', '<div id="__TEST3__">' + payload + '</div>');
    document.documentElement.setAttribute('data-test-done3', '1');
  })();
})();

param(
  [string]$Src = 'C:\Users\pedro.silva\Documents\Default Project\fluxo-dual.html',
  [string]$Harness = 'C:\Users\pedro.silva\AppData\Local\Temp\opencode\harness3.js',
  [string]$Tmp = 'C:\Users\pedro.silva\AppData\Local\Temp\opencode\fluxo-dual-test3.html'
)

# Lido explicitamente como UTF-8: evita que o PowerShell 5.1 interprete o
# .ps1/.js como ANSI e deturpe os acentos dentro das strings de conferência.
$h = Get-Content -Raw -Encoding UTF8 $Src
$js = Get-Content -Raw -Encoding UTF8 $Harness

$recorder = @'
<script>
window.__ERR = [];
window.addEventListener('error', function (e) { window.__ERR.push('ERR: ' + e.message + ' @' + e.lineno + ':' + e.colno); });
window.addEventListener('unhandledrejection', function (e) { var r = e.reason; window.__ERR.push('REJ: ' + ((r && r.stack) ? r.stack : r)); });
(function () { var ce = console.error;
  console.error = function () { window.__ERR.push('console.error: ' + Array.prototype.join.call(arguments, ' ')); return ce.apply(console, arguments); };
})();
</script>
'@

$m = [regex]::Match($h, '<body[^>]*>')
if (-not $m.Success) { throw 'body nao encontrado' }
$h = $h.Insert($m.Index + $m.Length, $recorder)

$harness = "`n<script>`n" + $js + "`n</script>`n"

$bi = $h.LastIndexOf('</body>')
if ($bi -lt 0) { throw 'body nao fechado' }
$h = $h.Insert($bi, $harness)

[System.IO.File]::WriteAllText($Tmp, $h, (New-Object System.Text.UTF8Encoding($false)))
Write-Output "BUILT $Tmp ($([math]::Round((Get-Item $Tmp).Length/1KB,1)) KB)"

