(function () {
  var R = { errors: (window.__ERR || []), steps: [] };
  var sleep = function (ms) { return new Promise(function (r) { setTimeout(r, ms); }); };
  function $(id) { return document.getElementById(id); }
  function cs(id) {
    var s = getComputedStyle($(id));
    return 'bg=' + s.backgroundColor + ' | color=' + s.color + ' | border=' + s.borderColor +
           ' | aria=' + $(id).getAttribute('aria-pressed');
  }
  function line(label, id) { R.steps.push(label + ' -> ' + cs(id)); }

  (async function () {
    await sleep(300);
    stopInertia();

    line('ANTES  consulta', 'tipoConsulta');
    line('ANTES  pronto   ', 'tipoPronto');
    info('ANTES  hint', $('tipoHint').textContent);

    $('tipoPronto').click();
    await sleep(400);

    line('DEPOIS consulta', 'tipoConsulta');
    line('DEPOIS pronto   ', 'tipoPronto');
    info('DEPOIS hint', $('tipoHint').textContent);
    info('rota1 data-urgente', $('btnRota1').dataset.urgente);
    info('rota1 bg', getComputedStyle($('btnRota1')).backgroundColor);
    info('avisco urg hidden', String($('tipoUrgente').hidden));

    $('tipoConsulta').click();
    await sleep(400);
    line('VOLTA  consulta', 'tipoConsulta');
    line('VOLTA  pronto   ', 'tipoPronto');
    info('VOLTA  rota1 bg', getComputedStyle($('btnRota1')).backgroundColor);

    info('erros', R.errors.length ? R.errors.join(' || ') : '(nenhum)');

    var payload = JSON.stringify(R).replace(/</g, '\\u003c');
    document.body.insertAdjacentHTML('beforeend', '<div id="__ST__">' + payload + '</div>');
    document.documentElement.setAttribute('data-st-done', '1');
  })();

  function info(n, v) { R.steps.push('      ' + n + ' = ' + v); }
})();

