function abrirSeletor(input, aoEscolher) {
  let settled = false;
  const finish = (file) => {
    if (settled) return;
    settled = true;
    input.removeEventListener('change', onChange);
    input.removeEventListener('cancel', onCancel);
    window.removeEventListener('focus', onFocus);
    aoEscolher(file);
