/**
 * refreshConfirm() — habilita/desabilita o "Confirmar".
 * Regras de negócio por MODO de atendimento:
 *   • consulta  → nome editável/preenchido E plano escolhido;
 *                 (escanear/anexar PDF só acelera: os 2 acabam preenchidos juntos)
 *   • pronto    → basta o NOME: não se pode recusar urgência por falta de
 *                 convênio (plano vira opcional e a consulta marcada nem existe).
 */
function refreshConfirm() {
  const urgente = state.tipoAtendimento === 'pronto';
  const nome    = el.fNome.value.trim();
  const plano   = el.fPlano.value !== '';

  const ok = urgente ? nome !== '' : (nome !== '' && plano);
  el.btnConfirmar.disabled = !ok;

  if (!nome) {
    el.dicaConfirmar.textContent = 'Digite seu nome (ou escaneie/anexe o documento) para continuar.';
  } else if (!urgente && !plano) {
