/**
 * abrirSeletor(input, aoEscolher) — abre um <input type="file"> nativo e
 * normaliza os 3 desfechos possíveis do diálogo do SO:
 *   1) arquivo escolhido  → aoEscolher(file);
 *   2) evento 'cancel'     → usuário desistiu → aoEscolher(null);
 *   3) navegador antigo    → sem 'cancel': heurística por volta de foco.
 * Usado pelos DOIS anexos: foto (câmera/galeria) e PDF.
 *
 * @param {HTMLInputElement} input     — input oculto de arquivo
 * @param {(f: File|null) => void} aoEscolher — callback do desfecho
 */
function abrirSeletor(input, aoEscolher) {
  let settled = false;

  const finish = (file) => {
    if (settled) return;
    settled = true;
    input.removeEventListener('change', onChange);
    input.removeEventListener('cancel', onCancel);
    window.removeEventListener('focus', onFocus);
    aoEscolher(file);
  };

  function onChange() {
    const f = input.files && input.files[0];
    if (f) finish(f); // caso contrário, deixa o 'cancel'/foco decidir
  }
  function onCancel() { finish(null); }
  function onFocus() {
    // Heurística para navegadores sem o evento 'cancel' (Chrome <113, Safari <16.4):
    // ao voltar o foco à janela, aguardamos 700ms (tempo do diálogo fechar)
    // e seguimos com null caso nenhum arquivo tenha sido selecionado.
    setTimeout(() => finish((input.files && input.files[0]) || null), 700);
  }

  input.addEventListener('change', onChange);
  input.addEventListener('cancel', onCancel);
  if (!('oncancel' in input)) window.addEventListener('focus', onFocus);

  // Reset para permitir escolher o MESMO arquivo de novo em re-escaneamentos.
  input.value = '';
  input.click();
}

/** Foto: câmera traseira no mobile (capture="environment") / galeria no desktop. */
function openCapture() {
  // Desistiu do diálogo → segue em modo demonstração (fluxo spec literal).
  abrirSeletor(el.fileInput, (f) => runOcr(f, f ? 'foto' : 'demo'));
}

