 *   A) btnScan    → spec literal: clique → loader de 2s → autofill (demo);
 *   B) btnCapture → captura REAL pela câmera/galeria nativa e OCR simulado.
 *   C) btnPdf     → anexo do ARQUIVO .pdf já digitalizado do documento.
 * -------------------------------------------------------------------------- */

/** Tamanho máximo aceito para o PDF anexado (evita travar o totem). */
const MAX_PDF_BYTES = 15 * 1024 * 1024; // 15 MB

/**
 * ehPdfValido(file) — valida o anexo antes de submeter ao leitor.
 * Aceita `application/pdf` ou extensão `.pdf` (alguns SOs enviam o type vazio).
 * Mostra o motivo da recusa em toast — nunca falha em silêncio.
 * @param {File|null} file
 * @returns {boolean}
 */
function ehPdfValido(file) {
  if (!file) return false;
  const nome = (file.name || '').toLowerCase();
  const parecePdf = file.type === 'application/pdf' || nome.endsWith('.pdf');

  if (!parecePdf) {
    showToast('⚠️ Isso não é um PDF. Use "Usar foto real" para imagens.', 4200);
    return false;
  }
  if (file.size > MAX_PDF_BYTES) {
    showToast('⚠️ PDF acima de 15 MB. Envie um arquivo menor.', 4200);
    return false;
  }
  return true;
}

/** C) ANEXAR PDF — arquivo digitalizado (assinatura/escaneamento salvo em PDF). */
el.btnPdf.addEventListener('click', () => {
  if (state.scanning) return;      // ignora toques durante a leitura
  abrirSeletor(el.pdfInput, (f) => {
