 * Mostra o motivo da recusa em toast — nunca falha em silêncio.
 * PONTO DE INTEGRAÇÃO REAL: no backend, adicionar também verificação de
 * assinatura binária (%PDF-), limite de páginas e scan de malware.
 * @param {File|null} file
 * @returns {boolean}
 */
function ehPdfValido(file) {
  if (!file) return false;
  const nome = (file.name || '').toLowerCase();
  const parecePdf = file.type === 'application/pdf' || nome.endsWith('.pdf');

  if (!parecePdf) {
    showToast('⚠️ Isso não é um PDF. Use "Usar foto real" para imagens.', 4200);
    return false;
  }
  if (file.size > MAX_PDF_BYTES) {
    showToast('⚠️ PDF acima de 15 MB. Envie um arquivo menor.', 4200);
    return false;
  }
  return true;
}

/** A) CTA PRINCIPAL — fluxo exatamente como especificado (sem diálogo nativo). */
el.btnScan.addEventListener('click', () => {
  if (state.scanning) return;  // ignora toques durante o OCR
  runOcr(null, 'demo');        // null = modo demonstração (2s)
});

/** B) CAPTURA REAL — abre o seletor nativo de imagem. */
el.btnCapture.addEventListener('click', () => {
  if (state.scanning) return;
  openCapture();
});

/** C) ANEXAR PDF — arquivo .pdf já digitalizado (assinatura/escaneamento). */
el.btnPdf.addEventListener('click', () => {
  if (state.scanning) return;  // ignora toques durante a leitura
  abrirSeletor(el.pdfInput, (f) => {
    // cancelou / recusado → não faz nada (mantém o que já estava preenchido).
    if (!ehPdfValido(f)) return;
    runOcr(f, 'pdf');
  });
});

