/**
 * runOcr(file, kind) — orquestra loading → OCR → preenchimento → sucesso.
 * @param {File|null} file — arquivo lido (null = modo demonstração)
 * @param {'demo'|'foto'|'pdf'} kind — origem da leitura (define textos/preview)
 */
async function runOcr(file, kind = 'demo') {
  if (state.scanning) return;
  const pdf = kind === 'pdf';

  // Re-escanear: limpa a tentativa anterior (não apaga nada do usuário
  // enquanto ele só escolhe — reset acontece aqui, dentro da leitura).
  if (state.docScanned) resetScanUI();
  state.scanning = true;
  state.docKind = kind;

  // --- UI: estado de carregamento ---------------------------------------
  el.btnScan.disabled = true;
  el.btnScan.classList.add('opacity-60', 'cursor-wait');
  el.btnPdf.disabled = true;
  el.scanIdle.hidden = true;
  el.scanDone.hidden = true;
  el.scanLoading.hidden = false;
  el.scanLoadingTitle.textContent = pdf
    ? 'Lendo PDF anexado…'
    : 'Lendo documento via OCR…';
  el.scanLoadingSub.textContent = pdf
    ? 'Extraindo nome e convênio do arquivo PDF'
    : 'Extraindo nome, convênio e horário da consulta';
  el.statusText.textContent = pdf ? 'Lendo PDF…' : 'Lendo documento…';

  if (file) {
    if (pdf) {
      // PDF não é imagem: NÃO jogamos no <img>. Mostramos o chip com o
      // nome do arquivo (e revogamos a foto anterior, se houver).
      if (state.previewUrl) { URL.revokeObjectURL(state.previewUrl); state.previewUrl = null; }
      el.scanPreview.hidden = true;
      el.scanPreview.removeAttribute('src');
      const mb = (file.size / (1024 * 1024));
      el.docChipNome.textContent = (file.name || 'documento.pdf') +
        ' · ' + (mb < 1 ? Math.max(1, Math.round(file.size / 1024)) + ' KB'
                          : mb.toFixed(1) + ' MB');
      el.docChip.hidden = false;
    } else {
      // Pré-visualização real da FOTO, com ObjectURL revogável (LGPD).
      if (state.previewUrl) URL.revokeObjectURL(state.previewUrl);
      state.previewUrl = URL.createObjectURL(file);
      el.scanPreview.src = state.previewUrl;
      el.scanPreview.hidden = false;
    }
  }

  try {
    // --- Chamada ao serviço (2s simulados dentro do serviço) -------------
    const data = await ocrService.scan(file, kind);

    // --- Preenchimento automático dos campos ----------------------------
    // O nome segue DIGITÁVEL: o OCR só sugere um valor inicial.
    el.fNome.value     = data.nome;
    aplicarPlano(data.convenio); // select de plano (OCR → dropdown)
    if (!state.tipoAtendimento || state.tipoAtendimento !== 'pronto') {
      el.fConsulta.value = data.consulta;
    }

    // Sinaliza "preenchido" (guarda informativa do bloco de dados).
    el.formResult.dataset.filled = 'true';
    state.docScanned = true;

    // --- Transição de UI: sucesso ----------------------------------------
    el.scanLoading.hidden = true;
    el.scanDone.hidden = false;
    el.scanDoneTitle.textContent = pdf
      ? 'PDF anexado com sucesso'
      : 'Documento lido com sucesso';

    el.btnScan.disabled = false;
    el.btnScan.classList.remove('opacity-60', 'cursor-wait');
    el.btnScan.innerHTML = '🔄 Escanear novamente';
    el.btnPdf.disabled = false;

    // Libera a ação finalizadora (revalida nome/segundo modo + plano).
    refreshConfirm();
    el.statusText.textContent = 'Documento identificado ✓';

    showToast(pdf    ? '✅ PDF anexado! Confira os dados.'
              : file ? '✅ Documento lido! Confira os dados.'
                     : '✅ Leitura concluída (modo demonstração).');
    analyticsService.track('ocr_success', {
      confidence: data.confidence,
      mode: kind
    });

  } catch (err) {
    // --- Tratamento de erro (rede/API indisponível, imagem ilegível) -----
    console.error('[OCR]', err);
    resetScanUI();
    showToast('⚠️ Não conseguimos ler o documento. Tente novamente, anexe o PDF ou digite o nome.', 4600);
    analyticsService.track('ocr_failure', { error: String(err) });
  } finally {
    state.scanning = false;
  }
}

/** Restaura a UI do scanner para o estado ocioso (e libera a memória da foto). */
function resetScanUI() {
  state.docScanned = false;
  state.docKind = null;
  state.scanning = false;
  el.scanIdle.hidden = false;
  el.scanLoading.hidden = true;
  el.scanDone.hidden = true;

  // Pré-visualização: esconde e revoga a ObjectURL (evita vazamento de memória
  // e garante que a foto do documento não permaneça no dispositivo).
  el.scanPreview.hidden = true;
  el.scanPreview.removeAttribute('src');
  if (state.previewUrl) {
    URL.revokeObjectURL(state.previewUrl);
    state.previewUrl = null;
  }
  el.fileInput.value = '';
  el.pdfInput.value = '';

  // Chip do arquivo PDF anexado (ATRIBUTO hidden — igual aos outros toggles).
  el.docChip.hidden = true;
  el.docChipNome.textContent = 'documento.pdf';

  // Textos padrão do carregamento (eram sobrescritos no modo PDF).
  el.scanLoadingTitle.textContent = 'Lendo documento via OCR…';
  el.scanLoadingSub.textContent   = 'Extraindo nome, convênio e horário da consulta';
  el.scanDoneTitle.textContent    = 'Documento lido com sucesso';

  // Nome volta a VAZIO (não "—"): o campo é digitável do zero.
  el.fNome.value = '';
  el.fPlano.value = '';
  el.fConsulta.value = '—';
  el.formResult.dataset.filled = 'false';

  el.btnScan.disabled = false;
  el.btnScan.classList.remove('opacity-60', 'cursor-wait');
  el.btnScan.innerHTML = '📷 Escanear documento';
  el.btnPdf.disabled = false;

  refreshConfirm();
  el.statusText.textContent = 'Check-in em andamento';
}

/**
 * Fallback de acessibilidade — "Digitar manualmente".
 * O formulário JÁ é editável (o nome aceita digitação livre); este link só
 * direciona o foco para o campo, garantindo o caminho manual obrigatório
 * em saúde (não depende de OCR/câmera/PDF estar disponível).
 */
el.btnManual.addEventListener('click', () => {
  el.fNome.focus();
  el.fNome.select();
  showToast('✍️ Digite o nome direto no campo e escolha o plano — sem depender do OCR.', 4200);
  analyticsService.track('manual_entry_used');
});

