/** AÇÃO FINALIZADORA — Confirmar e Finalizar (ou "Enviar para a triagem"). */
el.btnConfirmar.addEventListener('click', async () => {
  if (el.btnConfirmar.disabled) return;
  const urgente = state.tipoAtendimento === 'pronto';

  el.btnConfirmar.disabled = true;
  el.btnConfirmar.textContent = urgente ? 'Enviando para a triagem…' : 'Enviando…';
  el.statusText.textContent = urgente ? 'Acionando a triagem…' : 'Finalizando check-in…';

  /* PONTO DE INTEGRAÇÃO REAL — backend de agendamento/triagem:
     POST /v1/checkins  { patientId, appointmentId, status: 'ARRIVED', ts }
     → registra a chegada do paciente e libera a senha na fila interna.
     Em urgência o payload leva { priority: 'ALTA', route: 'TRIAGE' }. */
  await new Promise(r => setTimeout(r, 900));

  /* PONTO DE INTEGRAÇÃO REAL — fila da recepção (ver queueService). */
  const res = await queueService.dispatch(urgente ? 'PRONTO_SOCORRO_SELF' : 'CHECKIN_CONFIRMED');

  // Reset para o próximo usuário (dispositivo compartilhado / totem).
  resetScanUI();
  aplicarModoTela2();

  if (urgente) {
    // Pronto-socorro: a identificação dá direito à senha de TRIAGEM
    // (prioridade ALTA) — é aqui que o chamado é emitido.
    state.ticket = res.ticket;
    showToast('🚑 Triagem acionada — prioridade ALTA.');
    analyticsService.track('triage_issued', { priority: 'ALTA' });
    goTo('suporte');
    return;
  }

  showToast('🎉 Check-in concluído! Dirija-se à sala de espera.');

  // Volta ao estado inicial — pronto para novo atendimento.
  goTo('inicio');
});

