param(
  [string]$Acao = '',
  [int]$Altura = 900,
  [Parameter(Mandatory = $true)][string]$Saida
)
$ErrorActionPreference = 'Stop'
$src    = 'C:\Users\pedro.silva\Documents\Default Project\fluxo-dual.html'
$chrome = 'C:\Program Files\Google\Chrome\Application\chrome.exe'
$tmp    = "C:\Users\pedro.silva\AppData\Local\Temp\opencode\shot-src.html"

$h = Get-Content -Raw -Encoding UTF8 $src

# Cada acao: JS a executar apos load, delay (ms) e budget (ms).
# 'suporte' precisa de tempo extra: 900ms de envio + 250ms do dispatch + observer.
$map = @{
  ''             = @{ js = ''; delay = 600; budget = 6000 }
  'pronto'       = @{ js = "document.getElementById('tipoPronto').click();"; delay = 600; budget = 6000 }
  'chat'         = @{ js = "document.getElementById('btnIaLink').click();"; delay = 600; budget = 6000 }
  'consultaChat' = @{ js = "document.getElementById('tipoConsulta').click(); document.getElementById('btnIaLink').click();"; delay = 600; budget = 6000 }
  'checkin'      = @{ js = "stopInertia(); document.getElementById('tipoConsulta').click(); document.getElementById('btnRota1').click();"; delay = 700; budget = 7000 }
  'triagem'      = @{ js = "stopInertia(); document.getElementById('tipoPronto').click(); document.getElementById('btnRota1').click();"; delay = 700; budget = 7000 }
  'triagemPdf'   = @{ js = "stopInertia(); document.getElementById('tipoPronto').click(); document.getElementById('btnRota1').click(); setTimeout(function(){ var n=document.getElementById('fNome'); n.value='Joao Silva'; n.dispatchEvent(new Event('input',{bubbles:true})); runOcr(new File(['%PDF-1.4 x'],'carteirinha.pdf',{type:'application/pdf'}),'pdf'); },120);"; delay = 3000; budget = 9000 }
  'suporte'      = @{ js = "stopInertia(); document.getElementById('tipoPronto').click(); document.getElementById('btnRota1').click(); setTimeout(function(){ var n=document.getElementById('fNome'); n.value='Joao da Triagem'; n.dispatchEvent(new Event('input',{bubbles:true})); setTimeout(function(){ document.getElementById('btnConfirmar').click(); }, 60); }, 300);"; delay = 2600; budget = 9000 }
}

if (-not $map.ContainsKey($Acao)) { throw "Acao desconhecida: '$Acao'" }
$cfg = $map[$Acao]

$recorder = @'
<style>*, *::before, *::after { transition: none !important; animation: none !important; }</style>
<script>
window.__ERR=[];window.addEventListener('error',function(e){window.__ERR.push(e.message);});
setTimeout(function(){ try { __ACAO__ } catch(e) { window.__ERR.push(e.message); } }, __DELAY__);
</script>
'@
$recorder = $recorder.Replace('__ACAO__', $cfg.js).Replace('__DELAY__', [string]$cfg.delay)

$bi = $h.LastIndexOf('</body>')
if ($bi -lt 0) { throw 'body nao fechado' }
$h = $h.Insert($bi, $recorder)
[System.IO.File]::WriteAllText($tmp, $h, (New-Object System.Text.UTF8Encoding($false)))

if (Test-Path $Saida) { Remove-Item $Saida -Force }
