  }
  function info(n, v) { R.steps.push('      ' + n + ' = ' + v); }

  (async function () {
    await sleep(300);
    stopInertia();

    // --- Tela 2 em MODO CONSULTA ---
    document.getElementById('tipoConsulta').click();
    document.getElementById('btnRota1').click();
