    line('VOLTA      btnConf  ', 'btnConfirmar');
    info('VOLTA consulta card hidden', String($('fConsultaCard').hidden));

    info('erros', R.errors.length ? R.errors.join(' || ') : '(nenhum)');

    var payload = JSON.stringify(R).replace(/</g, '\\u003c');
    document.body.insertAdjacentHTML('beforeend', '<div id="__ST2__">' + payload + '</div>');
    document.documentElement.setAttribute('data-st2-done', '1');
