/* --------------------------------------------------------------
   MODO TRIAGEM NA TELA 2 (pronto-socorro).
   A Rota 1 leva à MESMA tela de identificação — mas em modo de
   triagem: o usuário escolhe a GRAVIDADE do caso (leve/moderada/
   crítica) e é ela que define a prioridade. Nada de marcar tudo
   como ALTA: o padrão é "A DEFINIR" (cinza) até a escolha.
   O estado vive em `data-*` nos 4 elementos, então nada de
   classes Tailwind geradas em runtime.

     eletivo   → consulta marcada (visual padrão brand)
     pendente  → pronto-socorro ainda sem gravidade escolhida
     normal    → gravidade leve      (verde)
     media     → gravidade moderada  (laranja)
     alta      → gravidade crítica   (vermelho)
   -------------------------------------------------------------- */
#etapaBadge[data-prio="pendente"] { background: #e2e8f0; color: #334155; }
#etapaBadge[data-prio="normal"]   { background: #dcfce7; color: #166534; }
#etapaBadge[data-prio="media"]    { background: #ffedd5; color: #9a3412; }
#etapaBadge[data-prio="alta"]     { background: #fee2e2; color: #991b1b; }

#etapaBar[data-prio="pendente"] { background: #94a3b8; }
#etapaBar[data-prio="normal"]   { background: #16a34a; }
#etapaBar[data-prio="media"]    { background: #f97316; }
#etapaBar[data-prio="alta"]     { background: #dc2626; }

#scanArea[data-prio="pendente"] { border-color: #cbd5e1; background: #f8fafc; }
#scanArea[data-prio="normal"]   { border-color: #86efac; background: #f0fdf4; }
#scanArea[data-prio="media"]    { border-color: #fdba74; background: #fff7ed; }
#scanArea[data-prio="alta"]     { border-color: #fca5a5; background: #fef2f2; }
#scanArea[data-prio="pendente"] .mira span { border-color: #94a3b8; }
#scanArea[data-prio="normal"]   .mira span { border-color: #16a34a; }
#scanArea[data-prio="media"]    .mira span { border-color: #f97316; }
#scanArea[data-prio="alta"]     .mira span { border-color: #dc2626; }

/* CTA só fica colorido de verdade quando a gravidade foi escolhida —
   antes disso permanece desabilitado em cinza (regra abaixo vence). */
#btnConfirmar[data-prio="media"] {
  background: #c2410c;
  box-shadow: 0 14px 28px -12px rgba(194, 65, 12, .7);
}
#btnConfirmar[data-prio="alta"] {
  background: #b91c1c;
  box-shadow: 0 14px 28px -12px rgba(185, 28, 28, .7);
}
#btnConfirmar[data-prio="normal"] {
  background: #0f766e;
  box-shadow: 0 14px 28px -12px rgba(15, 118, 110, .7);
}
#btnConfirmar[data-prio="media"]:not(:disabled):hover { background: #9a3412; }
#btnConfirmar[data-prio="alta"]:not(:disabled):hover  { background: #991b1b; }
#btnConfirmar[data-prio="normal"]:not(:disabled):hover { background: #115e59; }
/* Desabilitado: SEMPRE cinza, mesmo em urgência (senão parece ativo). */
#btnConfirmar[data-prio="media"]:disabled,
#btnConfirmar[data-prio="normal"]:disabled,
#btnConfirmar[data-prio="alta"]:disabled {
  background: #cbd5e1;
  box-shadow: none;
}

/* --------------------------------------------------------------
   CARTÃO DE TRIAGEM DE GRAVIDADE (só aparece no modo pronto)
   Três botões grandes, lado a lado, no padrão tátil do app.
   -------------------------------------------------------------- */
.grav-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  text-align: left;
  padding: 9px 10px;
  border: 2px solid #e2e8f0;
  border-radius: 16px;
  background: #f8fafc;
  cursor: pointer;
  transition: border-color .15s, background .15s, transform .15s;
}
.grav-btn:hover { border-color: #94a3b8; }
.grav-btn:active { transform: scale(.98); }
.grav-btn .grav-emoji { font-size: 20px; line-height: 1; }
.grav-btn .grav-rot {
  display: block;
  font-size: 14.5px;
  font-weight: 800;
  color: #0f172a;
}
.grav-btn .grav-ex {
  display: block;
  font-size: 11.5px;
  line-height: 1.3;
  color: #64748b;
}
.grav-btn .grav-prio {
  margin-left: auto;
  flex-shrink: 0;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .04em;
  padding: 3px 7px;
  border-radius: 999px;
  background: #e2e8f0;
  color: #475569;
}
/* Selecionada — a cor já avisa qual prioridade vai sair. */
.grav-btn[data-g="leve"][aria-pressed="true"] {
  border-color: #16a34a;
  background: #f0fdf4;
}
.grav-btn[data-g="leve"][aria-pressed="true"] .grav-prio {
  background: #16a34a;
  color: #fff;
}
.grav-btn[data-g="moderada"][aria-pressed="true"] {
  border-color: #f97316;
  background: #fff7ed;
}
.grav-btn[data-g="moderada"][aria-pressed="true"] .grav-prio {
  background: #f97316;
  color: #fff;
}
.grav-btn[data-g="critica"][aria-pressed="true"] {
  border-color: #dc2626;
  background: #fef2f2;
}
.grav-btn[data-g="critica"][aria-pressed="true"] .grav-prio {
  background: #dc2626;
  color: #fff;
}

