 *   • pronto    → NOME + GRAVIDADE: não se recusa urgência por falta de
 *                 convênio (plano opcional), mas a prioridade da fila só
 *                 existe depois que o caso é qualificado na triagem.
 */
function refreshConfirm() {
  const urgente = state.tipoAtendimento === 'pronto';
  const nome    = el.fNome.value.trim();
  const plano   = el.fPlano.value !== '';
  const semGrav = urgente && !state.gravidade;

  const ok = urgente ? (nome !== '' && !semGrav) : (nome !== '' && plano);
