input.newString:
/**
 * atualizarPrioridadeTela2() — pinta a Tela 2 conforme MODO + GRAVIDADE.
 * É quem define o data-prio de etapaBadge/etapaBar/scanArea/btnConfirmar
 * (o <style> colore; nunca geramos classes Tailwind em runtime).
 *
 *   consulta            → data-prio="eletivo"  (visual padrão brand)
 *   pronto sem escolha  → data-prio="pendente" (cinza, CTA bloqueado)
 *   pronto leve/mod/crítica → normal / media / alta
 */
function atualizarPrioridadeTela2() {
  const urgente = state.tipoAtendimento === 'pronto';
  const g = GRAVIDADES[state.gravidade] || null;
  const prio = urgente ? (g ? g.css : 'pendente') : 'eletivo';

  el.etapaBadge.dataset.prio = prio;
  el.etapaBadge.textContent = !urgente
    ? 'ÚLTIMO PASSO'
    : (g ? 'PRIORIDADE ' + g.prio : 'A DEFINIR');
  el.etapaBar.dataset.prio     = prio;
  el.etapaBar.dataset.urgente  = urgente ? '1' : '0';
  el.scanArea.dataset.prio     = prio;
  el.scanArea.dataset.urgente  = urgente ? '1' : '0';
  el.btnConfirmar.dataset.prio = prio;
  el.btnConfirmar.dataset.urgente = urgente ? '1' : '0';
}

/**
 * setGravidade() — escolha da triagem (só existe no modo pronto).
 * Cada tecla/ clique também renova o timer de inércia e registra o evento.
 * @param {string} g — 'leve' | 'moderada' | 'critica'
 */
function setGravidade(g) {
  if (state.tipoAtendimento !== 'pronto' || !GRAVIDADES[g]) return;
  state.gravidade = g;

  el.gravLeve.setAttribute('aria-pressed', String(g === 'leve'));
  el.gravModerada.setAttribute('aria-pressed', String(g === 'moderada'));
  el.gravCritica.setAttribute('aria-pressed', String(g === 'critica'));

  // Só em caso crítico lembramos do SAMU 192 (ATRIBUTO hidden).
  el.gravSamu.hidden = g !== 'critica';

  atualizarPrioridadeTela2();
  refreshConfirm();
  bumpInertia();
  analyticsService.track('triage_severity_selected', {
    gravidade: g,
    priority: GRAVIDADES[g].prio
  });
}

el.gravLeve.addEventListener('click', () => setGravidade('leve'));
el.gravModerada.addEventListener('click', () => setGravidade('moderada'));
el.gravCritica.addEventListener('click', () => setGravidade('critica'));

/**
 * aplicarModoTela2() — aplica o MODO da Tela 2 (consulta x pronto-socorro).
 * É a única fonte de verdade do texto/estilo dessa tela. Nada de classes
 * Tailwind geradas em runtime: usamos texto + atributos `data-*`, e o <style>
 * é quem colore (#etapaBadge/#etapaBar/#scanArea/#btnConfirmar[data-*]).
 * ATENÇÃO: não mexe em state.gravidade — quem zera é o btnRota1 ao entrar.
