+  el.etapaBar.dataset.urgente  = urgente ? '1' : '0';
+  el.scanArea.dataset.prio     = prio;
+  el.scanArea.dataset.urgente  = urgente ? '1' : '0';
+  el.btnConfirmar.dataset.prio = prio;
+  el.btnConfirmar.dataset.urgente = urgente ? '1' : '0';
