input.newString:
const urgente = state.tipoAtendimento === 'pronto';
const g = GRAVIDADES[state.gravidade] || null;

el.btnConfirmar.disabled = true;
el.btnConfirmar.textContent = urgente ? 'Enviando para a triagem…' : 'Enviando…';
el.statusText.textContent = urgente ? 'Acionando a triagem…' : 'Finalizando check-in…';

/* PONTO DE INTEGRAÇÃO REAL — backend de agendamento/triagem:
   POST /v1/checkins  { patientId, appointmentId, status: 'ARRIVED', ts }
   → registra a chegada do paciente e libera a senha na fila interna.
   Em urgência o payload leva { priority, severity, route: 'TRIAGE' } —
   priority NÃO é fixa: vem da GRAVIDADE escolhida na triagem. */
await new Promise(r => setTimeout(r, 900));

/* PONTO DE INTEGRAÇÃO REAL — fila da recepção (ver queueService).
   O reason registra a severidade para auditoria/telemetria da fila. */
const res = await queueService.dispatch(
  urgente
    ? 'PRONTO_SOCORRO_TRIAGE_' + (state.gravidade || 'NAO_INFORMADA').toUpperCase()
    : 'CHECKIN_CONFIRMED'
);

// Reset para o próximo usuário (dispositivo compartilhado / totem).
// ATENÇÃO: state.gravidade só zera DEPOIS que a Tela 4 renderizar os
// chips — quem limpa é limparGravidade(), na próxima Rota 1/reinício.
resetScanUI();
aplicarModoTela2();

if (urgente) {
  // Pronto-socorro: a senha de TRIAGEM sai com a prioridade do CASO
  // escolhido (NORMAL / MÉDIA / ALTA) — nunca é automática.
  state.ticket = res.ticket;
  showToast(urgente && g && g.prio === 'ALTA'
    ? '🚑 Triagem acionada — prioridade ALTA.'
    : `🚑 Triagem acionada — ${g ? g.ticket.toLowerCase() : 'prioridade a definir'}.`);
  analyticsService.track('triage_issued', {
    priority: g ? g.prio : 'INDIFINIDA',
    gravidade: state.gravidade
  });
  goTo('suporte');
  return;
}

input.oldString:
const urgente = state.tipoAtendimento === 'pronto';

el.btnConfirmar.disabled = true;
el.btnConfirmar.textContent = urgente ? 'Enviando para a triagem…' : 'Enviando…';
el.statusText.textContent = urgente ? 'Acionando a triagem…' : 'Finalizando check-in…';

/* PONTO DE INTEGRAÇÃO REAL — backend de agendamento/triagem:
   POST /v1/checkins  { patientId, appointmentId, status: 'ARRIVED', ts }
   → registra a chegada do paciente e libera a senha na fila interna.
   Em urgência o payload leva { priority: 'ALTA', route: 'TRIAGE' }. */
await new Promise(r => setTimeout(r, 900));

/* PONTO DE INTEGRAÇÃO REAL — fila da recepção (ver queueService). */
const res = await queueService.dispatch(urgente ? 'PRONTO_SOCORRO_SELF' : 'CHECKIN_CONFIRMED');

// Reset para o próximo usuário (dispositivo compartilhado / totem).
resetScanUI();
aplicarModoTela2();

if (urgente) {
  // Pronto-socorro: a identificação dá direito à senha de TRIAGEM
  // (prioridade ALTA) — é aqui que o chamado é emitido.
  state.ticket = res.ticket;
  showToast('🚑 Triagem acionada — prioridade ALTA.');
  analyticsService.track('triage_issued', { priority: 'ALTA' });
  goTo('suporte');
  return;
}

