-    chk('IA citou PRIORIDADE ALTA', ultimaBolha().indexOf('PRIORIDADE ALTA') >= 0, 'true');
+    chk('IA explicou a triagem de gravidade', ultimaBolha().indexOf('gravidade') >= 0, 'true');
+    chk('IA não prometeu mais ALTA fixa', ultimaBolha().indexOf('sai com **PRIORIDADE ALTA**') < 0, 'true');

     // SEGURANÇA CLÍNICA: sintoma nunca recebe orientação da IA
     $('chatInput').value = 'dor forte no peito';
     $('chatSend').click();

input.newString:
// ===== ROTA 1 EM URGÊNCIA: leva à Tela 2 em MODO TRIAGEM =====
chk('rota 1 segue em urgência', $('rota1Label').textContent, 'Ir direto à triagem');
$('btnRota1').click();
await sleep(80);
chk('rota1 (pronto) levou a', state.screen, 'checkin');
chk('modo urgente: etapa', $('etapaLabel').textContent, 'TRIAGEM · ATENDIMENTO IMEDIATO');
chk('modo urgente: título', $('titulo-checkin').textContent, 'Identifique-se para a triagem');
chk('modo urgente: consulta oculta', String($('fConsultaCard').hidden), 'true');
chk('modo urgente: CTA sinalizado', $('btnConfirmar').dataset.urgente, '1');
chk('modo urgente: rótulo do CTA', $('btnConfirmar').textContent.trim(), 'Enviar para a triagem ✓');

// ===== TRIAGEM DE GRAVIDADE (a prioridade NÃO é mais fixa em ALTA) =====
chk('cartão de gravidade visível', String($('gravCard').hidden), 'false');
chk('gravidade começa nula', String(state.gravidade), 'null');
chk('badge inicial: a definir', $('etapaBadge').textContent, 'A DEFINIR');
chk('badge inicial data-prio pendente', $('etapaBadge').dataset.prio, 'pendente');
chk('scanArea pendente (cinza)', $('scanArea').dataset.prio, 'pendente');
chk('CTA bloqueado sem gravidade', String($('btnConfirmar').disabled), 'true');
chk('dica cobra gravidade + nome', $('dicaConfirmar').textContent, 'Escolha a gravidade e digite seu nome para continuar.');
chk('aviso SAMU oculto no início', String($('gravSamu').hidden), 'true');

// 1) caso LEVE → prioridade NORMAL (verde)
$('gravLeve').click();
await sleep(30);
chk('gravidade = leve', state.gravidade, 'leve');
chk('badge leve: PRIORIDADE NORMAL', $('etapaBadge').textContent, 'PRIORIDADE NORMAL');
chk('badge leve data-prio', $('etapaBadge').dataset.prio, 'normal');
chk('CTA leve data-prio', $('btnConfirmar').dataset.prio, 'normal');
chk('CTA ainda bloqueado sem nome', String($('btnConfirmar').disabled), 'true');
chk('dica agora pede só o nome', $('dicaConfirmar').textContent, 'Digite seu nome (ou escaneie/anexe o documento) para continuar.');

// 2) caso CRÍTICO → prioridade ALTA (vermelho) + aviso do SAMU
$('gravCritica').click();
await sleep(30);
chk('gravidade = critica', state.gravidade, 'critica');
chk('badge crítica: PRIORIDADE ALTA', $('etapaBadge').textContent, 'PRIORIDADE ALTA');
chk('CTA crítica data-prio', $('btnConfirmar').dataset.prio, 'alta');
chk('barra da etapa data-prio alta', $('etapaBar').dataset.prio, 'alta');
chk('aviso SAMU visível na crítica', String($('gravSamu').hidden), 'false');
chk('aria-pressed crítica', $('gravCritica').getAttribute('aria-pressed'), 'true');

// 3) caso MODERADO → prioridade MÉDIA (laranja) — é o que vamos emitir
$('gravModerada').click();
await sleep(30);
chk('gravidade = moderada', state.gravidade, 'moderada');
chk('badge moderada: PRIORIDADE MÉDIA', $('etapaBadge').textContent, 'PRIORIDADE MÉDIA');
chk('badge moderada data-prio', $('etapaBadge').dataset.prio, 'media');
chk('scanArea moderada data-prio', $('scanArea').dataset.prio, 'media');
chk('CTA moderada data-prio', $('btnConfirmar').dataset.prio, 'media');
chk('aria-pressed moderada', $('gravModerada').getAttribute('aria-pressed'), 'true');
chk('aria-pressed crítica solta', $('gravCritica').getAttribute('aria-pressed'), 'false');
chk('aviso SAMU some fora da crítica', String($('gravSamu').hidden), 'true');

chk('nome editável em urgência (sem readonly)', String($('fNome').readOnly), 'false');
chk('HIT fNome (urgência)', hit('fNome'), 'OK');
chk('HIT btnPdf (urgência)', hit('btnPdf'), 'OK');
chk('confirmar bloqueado sem nome', String($('btnConfirmar').disabled), 'true');

// digitação manual basta em urgência (plano é opcional)
$('fNome').value = 'João da Triagem';
$('fNome').dispatchEvent(new Event('input', { bubbles: true }));
await sleep(40);
chk('urgência: só o nome já libera', String($('btnConfirmar').disabled), 'false');
chk('urgência: dica de plano opcional', $('dicaConfirmar').textContent, 'Pronto para a triagem — plano de saúde opcional.');

$('btnConfirmar').click();
await sleep(1600);
