  [string]$Marca  = '__TEST3__',
  [int]$Budget = 70000
)

$chrome = 'C:\Program Files\Google\Chrome\Application\chrome.exe'
$dom = & $chrome --headless=new --disable-gpu --no-sandbox --window-size=500,900 `
        --virtual-time-budget=$Budget --dump-dom "file:///$($Pagina -replace '\\','/')" 2>$null | Out-String

Add-Type -AssemblyName System.Web

# A fonte do harness contem o literal da marca: pegar SEMPRE a ULTIMA ocorrencia.
$ms = [regex]::Matches($dom, '<div id="' + $Marca + '">(.*?)</div>', 'Singleline')
if ($ms.Count -eq 0) { Write-Output 'SEM PAYLOAD'; exit 1 }

$json = [System.Web.HttpUtility]::HtmlDecode($ms[$ms.Count - 1].Groups[1].Value)
$o = $json | ConvertFrom-Json

Write-Output ('TOTAL=' + $o.steps.Count + ' FAIL=' + $o.fail)
$ojos = @($o.steps) | Where-Object { $_ -like 'FAIL*' }
foreach ($s in $ojos) { Write-Output $s }
$infos = @($o.steps) | Where-Object { $_ -like '      *' }
foreach ($s in $infos) { Write-Output $s }

if ($o.fail -gt 0) { exit 2 }

