  $saida = "C:\Users\pedro.silva\AppData\Local\Temp\opencode\g-$($x.acao).png"
  if (Test-Path $saida) { Remove-Item $saida -Force }
  & powershell -NoProfile -ExecutionPolicy Bypass -File "C:\Users\pedro.silva\AppData\Local\Temp\opencode\shot.ps1" `
      -Acao $x.acao -Altura $x.h -Saida $saida | Out-Null
  if (Test-Path $saida) {
    Write-Output ("OK   " + $x.acao + " -> " + (Get-Item $saida).Length + " bytes")
  } else {
    Write-Output ("FALTA " + $x.acao)
  }
}

