input.newString:
  /* --------------------------------------------------------------
     TELA DE ESPERA DO ATENDENTE (overlay "chamar atendente").
     Não é um loader mudo: é uma SALA DE ESPERA — timeline de 3
     passos, contador de tempo parado e posição na fila. O usuário
     ENXERGA que alguém está vindo, em vez de ficar no escuro.
     O estado de cada passo vive em `data-step` (nada de classes
     Tailwind geradas em runtime).
       pending → aguardando · active → em andamento · done → concluído
     -------------------------------------------------------------- */
  .wait-step { display: flex; align-items: flex-start; gap: 12px; text-align: left; }
  .wait-dot {
    flex-shrink: 0;
    display: grid; place-items: center;
    width: 27px; height: 27px;
    border: 2px solid rgba(255, 255, 255, .35);
    border-radius: 999px;
    background: rgba(255, 255, 255, .10);
    color: #94a3b8;
    font-size: 13px; font-weight: 900; line-height: 1;
    transition: background .2s, border-color .2s, color .2s;
  }
  .wait-rot {
    display: block;
    font-size: 14.5px; font-weight: 800; line-height: 1.3;
    color: #94a3b8;
    transition: color .2s;
  }
  .wait-sub {
    display: block;
    font-size: 12px; line-height: 1.35; margin-top: 2px;
    color: #64748b;
    transition: color .2s;
  }

  .wait-step[data-step="active"] .wait-dot {
    background: #fbbf24; border-color: #fbbf24; color: #78350f;
    animation: waitBlink 1.05s ease-in-out infinite;
  }
  .wait-step[data-step="active"] .wait-rot { color: #fde68a; }
  .wait-step[data-step="active"] .wait-sub { color: #fcd34d; }

  .wait-step[data-step="done"] .wait-dot {
    background: #34d399; border-color: #34d399; color: #064e3b;
    animation: none;
  }
  .wait-step[data-step="done"] .wait-rot { color: #ffffff; }
  .wait-step[data-step="done"] .wait-sub { color: #99f6e4; }

  @keyframes waitBlink { 0%, 100% { opacity: 1; } 50% { opacity: .4; } }

  @media (prefers-reduced-motion: reduce) {
    *, *::before, *::after {
      animation-duration: .01ms !important;
      animation-iteration-count: 1 !important;
      transition-duration: .01ms !important;
    }
  }
</style>

