input.newString:
/**
 * setPassoEspera(step, fase, sub) — atualiza um item da timeline de espera.
 * @param {HTMLElement} step  — <li> com data-step
 * @param {'pending'|'active'|'done'} fase
 * @param {string} [sub]      — texto secundário do passo
 */
function setPassoEspera(step, fase, sub) {
  step.dataset.step = fase;
  if (sub !== undefined) step.querySelector('.wait-sub').textContent = sub;
  const dot = step.querySelector('.wait-dot');
  dot.textContent = fase === 'done' ? '✓' : (fase === 'active' ? '…' : dot.dataset.n);
}

/** Zera todos os timers/contador da tela de espera (chamar em todo saída). */
function limparEspera() {
  (state.waitTimers || []).forEach(clearTimeout);
  state.waitTimers = [];
  if (state.waitTicker) {
    clearInterval(state.waitTicker);
    state.waitTicker = null;
  }
}

/**
 * chamarRecepcao(reason) — abre a TELA DE ESPERA e só resolve quando o
 * atendente chegar (automático) ou quando o usuário confirma/cancela.
 *
 * Caminho compartilhado pela Rota 2, pelo "Sim, chamar atendente" do modal
 * de inércia e pelo CTA de escalonamento do chat — os três mostram a MESMA
 * sala de espera, com:
 *   • nº do chamado emitido;
 *   • contador de tempo parado + quantas pessoas estão na frente;
 *   • timeline de 3 passos (enviado → designado → a caminho);
 *   • saídas sempre disponíveis (confirmar / falar com a IA / cancelar).
 *
 * PONTO DE INTEGRAÇÃO REAL — em produção esta sequência é substituída por
 * um WebSocket/SSE (ex.: wss://api.../v1/queue/{ticket}) que emite os
 * eventos ASSIGNED {agentName} e ARRIVED. Aqui é apenas simulado.
 *
 * @param {string} reason — motivo/report auditável do chamado
 * @returns {Promise<void>} resolve ao final da espera
 */
function chamarRecepcao(reason) {
  return new Promise(resolve => {
    // Se já houver uma espera em andamento, não cria uma segunda.
    if (state.esperandoAtendente) return resolve();

    limparEspera();
    state.esperandoAtendente = true;
    state.waitResolve = resolve;
    state.waitTicket = null;
    stopInertia(); // a espera substitui o modal de inércia

    // --- RESET VISUAL ------------------------------------------------
    el.waitTicket.textContent = 'Emitindo chamado…';
    el.waitTimer.textContent = '00:00';
    el.waitQueue.textContent = '—';
    el.waitStatus.textContent = 'Enviando seu chamado para a recepção…';
    el.waitAvatar.textContent = '🙋‍♀️';
    el.waitAttended.disabled = true; // libera só quando o chamado existir
    setPassoEspera(el.waitStep1, 'active', 'Conectando com o sistema da fila…');
    setPassoEspera(el.waitStep2, 'pending', 'Procurando alguém livre no balcão…');
    setPassoEspera(el.waitStep3, 'pending', 'Ainda na fila de espera…');

    el.callOverlay.classList.remove('hidden');
    el.callOverlay.classList.add('flex');
    el.statusText.textContent = 'Chamando recepção…';
    analyticsService.track('human_call_started', { reason });
    requestAnimationFrame(() => el.waitAttended.focus());

    // --- CONTADOR DE ESPERA (o relógio do usuário) --------------------
    state.waitSec = 0;
    state.waitTicker = setInterval(() => {
      state.waitSec += 1;
      const mm = String(Math.floor(state.waitSec / 60)).padStart(2, '0');
      const ss = String(state.waitSec % 60).padStart(2, '0');
      el.waitTimer.textContent = mm + ':' + ss;
    }, 1000);

    // --- CRONOGRAMA (simulado; aqui entraria o WebSocket) --------------
    const T = (ms, fn) => state.waitTimers.push(setTimeout(fn, ms));

    queueService.dispatch(reason).then(res => {
      if (!state.esperandoAtendente) return; // espera já foi cancelada
      state.waitTicket = res.ticket;
      el.waitTicket.textContent = 'Chamado ' + res.ticket;
      el.waitAttended.disabled = false;
      setPassoEspera(el.waitStep1, 'done', 'A recepção já recebeu o seu chamado.');
      setPassoEspera(el.waitStep2, 'active', 'Procurando alguém livre no balcão…');
      el.waitStatus.textContent = 'Chamado ' + res.ticket + ' registrado. Estamos chamando alguém do balcão…';
      el.waitQueue.textContent = '3';
    });

    T(2200, () => {                      // → ASSIGNED
      if (!state.esperandoAtendente) return;
      el.waitAvatar.textContent = '🚶‍♀️';
      setPassoEspera(el.waitStep2, 'done', 'Ana Paula foi designada ao seu chamado.');
      setPassoEspera(el.waitStep3, 'active', 'Saiu do balcão e está a caminho.');
      el.waitStatus.textContent = 'Ana Paula foi designada e já está a caminho 🚶‍♀️';
      el.waitQueue.textContent = '1';
    });

    T(4400, () => {                      // → EN_ROUTE (fila esvaziou)
      if (!state.esperandoAtendente) return;
      setPassoEspera(el.waitStep3, 'active', 'Chegando ao seu lado — fique onde está.');
      el.waitStatus.textContent = 'Ana está quase chegando 👋 Ninguém mais na sua frente.';
      el.waitQueue.textContent = '0';
    });

    T(6200, () => {                      // → ARRIVED
      if (!state.esperandoAtendente) return;
      setPassoEspera(el.waitStep3, 'done', 'Ana Paula chegou até você.');
      el.waitAvatar.textContent = '🤝';
      el.waitStatus.textContent = 'Atendente chegou! Dirija-se ao balcão B 👋';
    });

    T(7000, () => encerrarEspera(true));  // → Tela 4 (suporte ativo)
  });
}

/**
 * encerrarEspera(chegou) — fecha a sala de espera.
 * @param {boolean} chegou — true = atendente atendeu (→ Tela 4);
 *                           false = usuário cancelou (volta de onde saiu)
 */
function encerrarEspera(chegou) {
  if (!state.esperandoAtendente) return;

  const resolve = state.waitResolve;
  state.waitResolve = null;
  limparEspera();

  el.callOverlay.classList.add('hidden');
  el.callOverlay.classList.remove('flex');
  state.esperandoAtendente = false;

  if (chegou) {
    state.ticket = state.waitTicket;
    analyticsService.track('human_call_arrived', { ticket: state.waitTicket });
    goTo('suporte');
  } else {
    analyticsService.track('human_call_cancelled', { ticket: state.waitTicket });
    state.ticket = null;   // chamado abandonado não pode aparecer na Tela 4
    el.statusText.textContent = statusDoHeader(state.screen);
    startInertia();        // retoma a inércia (aqui a tela já está "viva")
    showToast('Chamado cancelado. Continuamos por aqui se precisar. 🙂', 3600);
  }

  if (resolve) resolve();
}

input.oldString:
/**
 * chamarRecepcao(reason) — emite o chamado humano e leva à Tela 4.
 * Caminho compartilhado pela Rota 2, pelo atalho do modal de inércia e
 * pelo CTA de escalonamento do chat.
 * PONTO DE INTEGRAÇÃO REAL: o `reason` vira o payload de triagem
 * ({ priority, severity } — leve/moderada/crítica; nunca fixo em ALTA).
 * @param {string} reason — motivo/report auditável do chamado
 */
async function chamarRecepcao(reason) {
  // 1) Overlay "Chamando recepção…" (feedback imediato = percepção de velocidade)
  el.callOverlay.classList.remove('hidden');
  el.callOverlay.classList.add('flex');
  el.statusText.textContent = 'Chamando recepção…';

  // 2) Dispara o chamado no sistema de fila (aqui: simulado ~1.6s)
  const res = await queueService.dispatch(reason);
  await new Promise(r => setTimeout(r, 1600));

  // 3) Esconde overlay e segue para a Tela 4 (Sucesso / Suporte acionado)
  el.callOverlay.classList.add('hidden');
  el.callOverlay.classList.remove('flex');

  state.ticket = res.ticket;
  goTo('suporte');
}

