function abrirEspera(reason) {
  return new Promise(resolve => {
    state.esperandoAtendente = true;
    state.waitResolve = resolve;
    stopInertia();

    // reseta a UI para o início da espera
    el.waitTicket.textContent = 'Chamado sendo emitido…';
    el.waitTimer.textContent = '00:00';
    el.waitQueue.textContent = '—';
    el.waitStatus.textContent = 'Enviando seu chamado para a recepção…';
    el.waitAvatar.textContent = '🙋‍♀️';
    setPasso(el.waitStep1, 'active', 'Conectando com o sistema da fila…');
    setPasso(el.waitStep2, 'pending', 'Aguardando um atendente livre…');
    setPasso(el.waitStep3, 'pending', 'A caminho até você…');
    // reabilita botões
    el.waitAttended.disabled = false;

    el.callOverlay.classList.remove('hidden');
    el.callOverlay.classList.add('flex');
    el.statusText.textContent = 'Chamando recepção…';
    analyticsService.track('human_call_started', { reason });

    // contador de espera (sensação de "estou esperando")
    state.waitSec = 0;
    state.waitTicker = setInterval(() => {
      state.waitSec++;
      const m = String(Math.floor(state.waitSec/60)).padStart(2,'0');
      const s = String(state.waitSec%60).padStart(2,'0');
      el.waitTimer.textContent = `${m}:${s}`;
    }, 1000);

    // PONTO DE INTEGAÇÃO REAL: WebSocket /v1/queue → eventos    //   ASSIGNED {agentName} · EN_ROUTE · ARRIVED
    const T = (ms, fn) => state.waitTimers.push(setTimeout(fn, ms));

    queueService.dispatch(reason).then(res => {
      if (!state.esperandoAtendente) return;
      state.waitTicket = res.ticket;
      state.ticket = res.ticket;
      el.waitTicket.textContent = `Chamado ${res.ticket}`;
      setPasso(el.waitStep1, 'done', 'A recepção já recebeu o seu chamado.');
      setPasso(el.waitStep2, 'active', 'Procurando um atendente livre…');
      el.waitStatus.textContent = `Chamado ${res.ticket} registrado. Estamos chamando alguém do balcão…`;
      el.waitQueue.textContent = '3';
      chatService.open(res.ticket);   // hmm? no — skip
    });

    T(1700, () => { ...designada... });
    T(3700, () => { ...a caminho... });
    T(5600, () => encerrarEspera(true));
  });
}
