function onInertiaExpired() {
  // Não interrompe: (a) tela fora do fluxo, (b) modal já aberto,
  // (c) chat de IA aberto (usuário está engajado em conversa),
  // (d) o usuário está AGUARDANDO o atendente (a espera é a tela da vez).
  if (!INERTIA_SCREENS.includes(state.screen) ||
      state.inertiaModalOpen || state.chatOpen || state.esperandoAtendente) return;
  openInertiaModal();
  analyticsService.track('inertia_triggered', { screen: state.screen });
}

